"use strict";
window.QUESTIONS = [
  {"id":1,"category":"生産の基本","text":"TPMとは「全員参加の生産保全」を意味する活動である。","answer":true,"explanation":"TPM（Total Productive Maintenance）は、トップから第一線のオペレーターまで全部門・全員が参加して、設備の効率を最高にする生産保全活動です。"},
  {"id":2,"category":"生産の基本","text":"自主保全とは、保全部門の専門スタッフだけが設備の保全を行う活動である。","answer":false,"explanation":"自主保全は、設備を使うオペレーター自身が「自分の設備は自分で守る」という考えで行う保全活動です。専門保全（保全部門）と役割分担して進めます。"},
  {"id":3,"category":"生産の基本","text":"5Sとは、整理・整頓・清掃・清潔・しつけの5つである。","answer":true,"explanation":"整理・整頓・清掃・清潔・しつけの頭文字Sをとって5S。前の3S（整理・整頓・清掃）を維持する状態が清潔、それを習慣づけるのがしつけです。"},
  {"id":4,"category":"生産の基本","text":"「整理」とは、必要なものを使いやすく並べることである。","answer":false,"explanation":"整理は「要るものと要らないものを分け、要らないものを捨てる」こと。使いやすく置き場所・置き方を決めるのは「整頓」です。両者の区別は頻出です。"},
  {"id":5,"category":"生産の基本","text":"整頓の基本は「定位置・定品・定量」の3定である。","answer":true,"explanation":"どこに（定位置）・何を（定品）・どれだけ（定量）置くかを決め、表示することで、誰でもすぐ取り出せ、戻せる状態をつくります。"},
  {"id":6,"category":"生産の基本","text":"QCDとは、Quality（品質）・Cost（コスト）・Delivery（納期）を指す。","answer":true,"explanation":"生産管理の基本指標。この3つに安全（Safety）・モラール（Morale）を加えてPQCDSMと表すこともあります。"},
  {"id":7,"category":"生産の基本","text":"PDCAサイクルのAはAction（処置・改善）を表す。","answer":true,"explanation":"Plan（計画）→Do（実行）→Check（評価）→Action（処置）を繰り返して継続的に改善を進める管理サイクルです。"},
  {"id":8,"category":"生産の基本","text":"「なぜなぜ分析」は、なぜを繰り返して真の原因（真因）を突き止める手法である。","answer":true,"explanation":"「なぜ」を5回程度繰り返し、表面的な現象でなく根本原因にたどり着く手法。対策を真因に打つことで再発を防ぎます。"},
  {"id":9,"category":"生産の基本","text":"三現主義とは「現場・現物・現実」を重視する考え方である。","answer":true,"explanation":"机上でなく、現場に行き、現物を見て、現実を確認して判断する。問題解決の基本姿勢です。"},
  {"id":10,"category":"生産の基本","text":"安全の「ヒヤリ・ハット」とは、災害には至らなかったが、ひやりとした事例のことである。","answer":true,"explanation":"重大災害の陰に多数の軽微な事故とヒヤリ・ハットがあるとするハインリッヒの法則の考え方から、これを収集し未然防止に活かします。"},
  {"id":11,"category":"生産の基本","text":"KY活動（危険予知活動）は、作業前に潜む危険を予測し対策を話し合う活動である。","answer":true,"explanation":"Kiken（危険）Yochi（予知）の頭文字。作業に取りかかる前に危険要因を洗い出し、指差呼称などで安全を確保します。"},
  {"id":12,"category":"生産の基本","text":"標準作業とは、その日の作業者の判断で自由に手順を変えてよい作業のことである。","answer":false,"explanation":"標準作業は、最も安全で品質・能率のよい手順を定めたもの。誰がやっても同じ結果になるよう守るべきもので、勝手に変えるものではありません。"},
  {"id":13,"category":"生産の基本","text":"整理・整頓が進むと、不要品による探すムダや置き場のムダが減る。","answer":true,"explanation":"要るものだけを決めた場所に置くことで、探す時間・取りに行く距離・在庫のムダが減り、生産性と安全が向上します。"},
  {"id":14,"category":"生産の基本","text":"「見える化（目で見る管理）」とは、正常・異常を誰でも一目で判断できるようにする工夫である。","answer":true,"explanation":"あんどん、油面ライン、合マーク、区画線などで、異常をひと目でわかるようにし、早期発見・早期処置につなげます。"},
  {"id":15,"category":"生産の基本","text":"改善（カイゼン）は、大きな設備投資を伴うものだけを指す。","answer":false,"explanation":"改善は現場の小さな工夫の積み重ねも含みます。「金をかけずに知恵を出す」のが基本で、誰でもできる小改善の積み上げが重視されます。"},
  {"id":16,"category":"生産の基本","text":"5W1Hの要素には、When・Where・Who・What・Why・Howが含まれる。","answer":true,"explanation":"いつ・どこで・誰が・何を・なぜ・どのように。作業や問題を整理・報告するときの基本の枠組みです。"},
  {"id":17,"category":"設備の日常保全","text":"自主保全の基本三要素は「清掃・給油・増し締め」である。","answer":true,"explanation":"清掃・給油・増し締めは、設備の基本条件を整えて劣化を防ぐ日常保全の三本柱です。"},
  {"id":18,"category":"設備の日常保全","text":"「清掃は点検なり」といわれるように、清掃は点検を兼ねた活動である。","answer":true,"explanation":"汚れを取る過程で、ゆるみ・傷・漏れ・異音などの微欠陥を五感で発見できます。清掃は単なる掃除でなく点検活動です。"},
  {"id":19,"category":"設備の日常保全","text":"発生源・困難箇所対策では、まず汚れを掃除しやすくすることが最優先である。","answer":false,"explanation":"最優先は「汚れの発生源そのものを断つ」こと。発生源対策が難しい場合に、飛散防止や清掃しやすくする対策を行います。"},
  {"id":20,"category":"設備の日常保全","text":"ボルトの「合マーク（合わせマーク）」は、ゆるみを一目で発見するための表示である。","answer":true,"explanation":"ナットと相手部材にまたがる線を引いておき、線がずれれば増し締め不足やゆるみが一目でわかります。目で見る管理の代表例です。"},
  {"id":21,"category":"設備の日常保全","text":"潤滑油の主な役割は、摩擦を大きくして部品の動きを止めることである。","answer":false,"explanation":"潤滑の役割は摩擦・摩耗の低減が第一。ほかに冷却、防錆、密封、洗浄（ごみの運び出し）、応力分散などの働きがあります。"},
  {"id":22,"category":"設備の日常保全","text":"グリースは、基油に増ちょう剤を加えた半固体状の潤滑剤である。","answer":true,"explanation":"グリースは飛散しにくく、給油間隔を長くとれる、密封性がよいなどの利点があり、頻繁に給油できない箇所に向きます。"},
  {"id":23,"category":"設備の日常保全","text":"給油では、油種が違っても粘度が同じなら混ぜて使ってよい。","answer":false,"explanation":"油種・銘柄の異なる油の混用は、添加剤の反応や性能低下を招くおそれがあり避けます。指定された油種・粘度を守るのが原則です。"},
  {"id":24,"category":"設備の日常保全","text":"油面計（オイルゲージ）が汚れていても、油量さえ入っていれば管理上問題ない。","answer":false,"explanation":"油面計が汚れていると油量を正しく確認できません。清掃・見える化して、確実に点検できる状態を保つことが必要です。"},
  {"id":25,"category":"設備の日常保全","text":"日常点検は、設備を止めずに稼働状態のまま行う点検が中心である。","answer":true,"explanation":"日常点検は運転中の温度・振動・音・漏れなどを五感で確認するのが中心。分解を伴う精密点検は定期点検で行います。"},
  {"id":26,"category":"設備の日常保全","text":"設備の劣化には、使用による劣化のほか、放置（自然）による劣化もある。","answer":true,"explanation":"使用劣化（摩耗・疲労等）と自然劣化（さび・腐食・ほこりの堆積等）があり、いずれも清掃・給油・点検などの基本活動で防ぎます。"},
  {"id":27,"category":"設備の日常保全","text":"「強制劣化」とは、清掃・給油・増し締めを怠って本来防げる劣化を進めてしまうことである。","answer":true,"explanation":"基本条件の整備を怠って起こる、人為的で防げるはずの劣化を強制劣化といいます。これを防ぐことが自主保全の狙いです。"},
  {"id":28,"category":"設備の日常保全","text":"暫定基準（仮基準）とは、清掃・給油・増し締めの当面守るべき項目・周期・時間を定めたものである。","answer":true,"explanation":"自主保全の第3ステップで作る、誰でも確実に短時間で維持できる暫定的な基準です。活動の中で見直し改善していきます。"},
  {"id":29,"category":"設備の日常保全","text":"エアフィルタやオイルミストの点検・交換も、日常保全の対象に含まれる。","answer":true,"explanation":"空圧機器のフィルタ・ルブリケータ・ドレンなども、汚れや水分の管理を怠ると機器不調の原因になるため日常保全の対象です。"},
  {"id":30,"category":"設備の日常保全","text":"締結部のゆるみは、振動や騒音、部品の脱落・破損の原因になる。","answer":true,"explanation":"ボルトのゆるみは振動を増やし、さらにゆるみを進め、最終的に脱落・故障・事故につながります。増し締めと合マーク管理が重要です。"},
  {"id":31,"category":"設備の日常保全","text":"清掃で微欠陥を見つけたら、その場で処置するか「エフ（不具合札）」を付けて管理する。","answer":true,"explanation":"発見した不具合にエフを付けて見える化し、対応済みで外していくことで、微欠陥の摘出と復元の進捗を管理します。"},
  {"id":32,"category":"設備の日常保全","text":"点検作業を短時間・確実にするには、点検箇所の集中化や見える化が有効である。","answer":true,"explanation":"点検口の集約、透明カバー化、色分け表示、給油口の一元化などで、点検・給油の困難箇所をなくし作業を容易にします。"},
  {"id":33,"category":"効率化とロス","text":"設備総合効率は「時間稼働率 × 性能稼働率 × 良品率」で求められる。","answer":true,"explanation":"設備総合効率（OEE）はこの3要素の積。設備が持てる能力をどれだけ有効に発揮できたかを総合的に示します。"},
  {"id":34,"category":"効率化とロス","text":"時間稼働率は、故障・段取り・調整などによる停止ロスに関係する指標である。","answer":true,"explanation":"時間稼働率＝稼働時間÷負荷時間。停止ロス（故障、段取り・調整、立上りなど）が大きいほど低下します。"},
  {"id":35,"category":"効率化とロス","text":"性能稼働率は、チョコ停・空転や速度低下のロスに関係する指標である。","answer":true,"explanation":"性能稼働率は、基準サイクルタイムに対する実際の速度・小停止を反映します。チョコ停や速度低下ロスで低下します。"},
  {"id":36,"category":"効率化とロス","text":"故障ロスは、設備効率を阻害する7大ロスの一つである。","answer":true,"explanation":"故障ロスは代表的な阻害ロス。ほかに段取り・調整、刃具交換、立上り、チョコ停・空転、速度低下、不良・手直しの各ロスがあります。"},
  {"id":37,"category":"効率化とロス","text":"チョコ停とは、設備が長時間停止し、専門の修理を要する状態のことである。","answer":false,"explanation":"チョコ停は数分以内の一時的な小停止・空転で、詰まり除去やリセットなど簡単な処置ですぐ復旧するもの。部品交換や修理を要する「故障」とは区別します。"},
  {"id":38,"category":"効率化とロス","text":"チョコ停は一件が軽微なため見逃されやすいが、積み重なると性能稼働率を大きく下げる。","answer":true,"explanation":"一回の停止は短くても頻発すると累積損失は大きく、原因が特定しにくいため軽視されがちです。実は重要なロスです。"},
  {"id":39,"category":"効率化とロス","text":"段取り・調整ロスの短縮（シングル段取り化など）は、稼働率向上につながる。","answer":true,"explanation":"段取り替え時間を1桁分（10分未満）に縮めるシングル段取りなどで停止時間を減らし、時間稼働率を高めます。"},
  {"id":40,"category":"効率化とロス","text":"立上りロスとは、始業時や段取り替え後、生産が安定するまでに生じるロスである。","answer":true,"explanation":"設備の暖機や条件出しで、安定した良品が出るまでに発生するロス。7大ロスの一つです。"},
  {"id":41,"category":"効率化とロス","text":"速度低下ロスとは、設備を設計・基準速度より遅く動かすことで生じるロスである。","answer":true,"explanation":"品質不安や設備トラブルを避けるため速度を落として運転すると、性能稼働率が下がります。本来速度との差がロスです。"},
  {"id":42,"category":"効率化とロス","text":"不良・手直しロスは、良品率を低下させ設備総合効率を悪化させる。","answer":true,"explanation":"不良品や手直しが必要な製品の発生は良品率を直接下げ、材料・時間のムダにもなります。"},
  {"id":43,"category":"効率化とロス","text":"「ロス」を金額や件数で見える化することは、改善の優先順位づけに役立つ。","answer":true,"explanation":"ロスを定量化すると、どこから手を付ければ効果が大きいかが判断でき、重点指向の改善ができます。"},
  {"id":44,"category":"効率化とロス","text":"設備のロスだけでなく、人（作業）や原単位（材料・エネルギー）のロスも管理の対象になる。","answer":true,"explanation":"TPMでは16大ロスとして、設備・人・原単位の各ロスを体系的に捉え、総合的な効率化を目指します。"},
  {"id":45,"category":"効率化とロス","text":"故障には、機能停止型故障のほかに、機能低下型故障がある。","answer":true,"explanation":"完全に止まる機能停止型と、性能や品質が徐々に落ちる機能低下型があります。後者は気づきにくく見逃されがちです。"},
  {"id":46,"category":"効率化とロス","text":"設備総合効率を高めるには、7大ロスをバランスよく減らしていく必要がある。","answer":true,"explanation":"どれか一つを潰しても他が大きければ効率は上がりません。各ロスを見える化して総合的に改善します。"},
  {"id":47,"category":"効率化とロス","text":"良品率とは、投入数に対する良品数の割合のことである。","answer":true,"explanation":"良品率＝良品数÷投入（加工）数。不良・手直しが多いほど低下し、設備総合効率を押し下げます。"},
  {"id":48,"category":"効率化とロス","text":"稼働率を上げるためなら、品質不良が増えても問題ない。","answer":false,"explanation":"稼働率だけ上げても不良が増えれば良品率が下がり、設備総合効率はかえって悪化します。QCDのバランスが大切です。"},
  {"id":49,"category":"改善・解析","text":"パレート図は、項目を件数や金額の大きい順に並べ、重点課題を見つけるのに使う。","answer":true,"explanation":"大きい順の棒グラフと累積曲線で表し、「重要な少数（重点指向）」を見つけるQC手法。どこから改善するかの判断に使います。"},
  {"id":50,"category":"改善・解析","text":"特性要因図は、その形から「魚の骨（フィッシュボーン）図」とも呼ばれる。","answer":true,"explanation":"特性（結果）に対する要因を大骨・小骨状に整理する図。要因を4M（人・設備・材料・方法）などで洗い出します。"},
  {"id":51,"category":"改善・解析","text":"ヒストグラムは、データのばらつき（分布の形）を把握するために用いる。","answer":true,"explanation":"データを区間ごとの度数の柱で表し、分布の中心位置・ばらつき・形の異常（二山・離れ島など）を読み取ります。"},
  {"id":52,"category":"改善・解析","text":"散布図は、対になった2種類のデータの相関関係を調べるのに使う。","answer":true,"explanation":"2変数の点をプロットし、正の相関・負の相関・無相関を視覚的に判断します。原因と結果の関係を探るのに有効です。"},
  {"id":53,"category":"改善・解析","text":"チェックシートは、データを取りながら簡単に記録・集計できるよう作った記入用紙である。","answer":true,"explanation":"あらかじめ項目を印刷し、チェックを入れるだけで記録・集計できる、データ収集の基本ツールです。"},
  {"id":54,"category":"改善・解析","text":"管理図は、工程が安定しているか（異常がないか）を時系列で判断するのに使う。","answer":true,"explanation":"中心線と上下の管理限界線を引き、点が限界を超えたり並び方に癖があれば異常と判断します。工程の安定性監視に使います。"},
  {"id":55,"category":"改善・解析","text":"QC七つ道具には、パレート図・特性要因図・ヒストグラム・散布図・チェックシート・グラフ（管理図）・層別が含まれる。","answer":true,"explanation":"主に数値データを扱う7つの手法。言語データを整理する新QC七つ道具（親和図法など）とは別物です。"},
  {"id":56,"category":"改善・解析","text":"層別とは、データを機械別・人別・時間別などのグループに分けて解析する考え方である。","answer":true,"explanation":"データを共通点でグループ分けすると、どこに問題があるかが見えやすくなります。他の手法と組み合わせて使う基本の考え方です。"},
  {"id":57,"category":"改善・解析","text":"特性要因図の要因を洗い出すとき、4M（Man・Machine・Material・Method）の視点が役立つ。","answer":true,"explanation":"人・設備・材料・方法の4つの観点で要因を漏れなく挙げると、抜けの少ない解析ができます。"},
  {"id":58,"category":"改善・解析","text":"改善は「思いつき」で対策するより、データで事実を確認してから進める方がよい。","answer":true,"explanation":"事実に基づく管理（ファクトコントロール）が基本。データで現状と原因を確認し、効果も数値で検証します。"},
  {"id":59,"category":"改善・解析","text":"ECRSの原則とは、排除・結合・交換（組替え）・簡素化の順で改善を検討する考え方である。","answer":true,"explanation":"Eliminate（なくせないか）→Combine（一緒にできないか）→Rearrange（順序を変えられないか）→Simplify（簡単にできないか）の順で検討します。"},
  {"id":60,"category":"改善・解析","text":"改善の効果は、対策前後を比較して定量的に確認する必要はない。","answer":false,"explanation":"効果は対策前後のデータで比較し、狙いどおり改善したかを確認します。効果が出ていなければ原因分析からやり直します。"},
  {"id":61,"category":"改善・解析","text":"「歯止め（標準化）」とは、改善した状態を維持するために標準を定めることである。","answer":true,"explanation":"効果を確認したら、作業標準や点検基準に反映して誰でも守れるようにし、元に戻らないよう歯止めをかけます。"},
  {"id":62,"category":"改善・解析","text":"グラフは、数値の大小や変化、割合を視覚的にわかりやすく伝えるのに有効である。","answer":true,"explanation":"棒グラフ（大小）、折れ線（変化）、円グラフ（割合）など、目的に応じて使い分けると情報が伝わりやすくなります。"},
  {"id":63,"category":"改善・解析","text":"なぜなぜ分析では、対策しやすい原因が見つかった時点で分析をやめるのが望ましい。","answer":false,"explanation":"対策のしやすさで途中でやめると真因に届きません。「なぜ」を繰り返し、根本原因に対策を打つことで再発を防ぎます。"},
  {"id":64,"category":"改善・解析","text":"パレート図で上位の少数項目に対策を集中させる考え方を「重点指向」という。","answer":true,"explanation":"全体の大部分を占める少数の重要項目（重点）に資源を集中させると、効率よく効果を出せます。"},
  {"id":65,"category":"設備保全の基礎","text":"予防保全（PM）とは、故障が起きてから修理する保全のことである。","answer":false,"explanation":"予防保全は故障を未然に防ぐための保全。故障してから対応するのは事後保全（BM）です。"},
  {"id":66,"category":"設備保全の基礎","text":"事後保全（BM）は、設備が故障・停止してから修理・復旧する保全方式である。","answer":true,"explanation":"Breakdown Maintenance。壊れてから直す方式で、故障しても影響の小さい設備などで意図的に採用されることもあります。"},
  {"id":67,"category":"設備保全の基礎","text":"時間基準保全（TBM）は、一定の期間ごとに点検・部品交換を行う予防保全である。","answer":true,"explanation":"Time Based Maintenance。稼働時間や暦（例：3か月ごと）に基づいて定期的に保全する方式です。"},
  {"id":68,"category":"設備保全の基礎","text":"状態基準保全（CBM）は、設備の状態を診断し、劣化の程度に応じて保全する方式である。","answer":true,"explanation":"Condition Based Maintenance。振動・温度・油分析などで劣化を把握し、必要なときに保全する予知保全的な方式です。"},
  {"id":69,"category":"設備保全の基礎","text":"改良保全（CM）とは、故障しにくいように設備そのものを改善する活動である。","answer":true,"explanation":"Corrective Maintenance。材質変更や構造改良で信頼性・保全性を高め、故障や劣化そのものを減らします。"},
  {"id":70,"category":"設備保全の基礎","text":"保全予防（MP）とは、設計・製作の段階から保全しやすく故障しにくい設備をつくる活動である。","answer":true,"explanation":"Maintenance Prevention。新設備の計画・設計段階で、過去の保全情報を反映し、故障や保全の手間が少ない設備を目指します。"},
  {"id":71,"category":"設備保全の基礎","text":"ベアリング（転がり軸受）は、摩擦を利用して回転を止めるための部品である。","answer":false,"explanation":"ベアリングは、玉やころの転がりによって回転部の摩擦を減らし、滑らかに回すための部品です。"},
  {"id":72,"category":"設備保全の基礎","text":"Vベルトは、断面がV字形で、プーリ（滑車）間の動力伝達に用いられる。","answer":true,"explanation":"Vベルトはプーリの溝に食い込み、摩擦で動力を伝えます。張力の管理不足はすべりや早期摩耗の原因になります。"},
  {"id":73,"category":"設備保全の基礎","text":"歯車（ギヤ）は、かみ合いによって回転や動力を確実に伝えることができる。","answer":true,"explanation":"歯車はすべりが少なく、回転比（減速・増速）を正確に伝えられます。潤滑不良は摩耗・欠けの原因になります。"},
  {"id":74,"category":"設備保全の基礎","text":"油圧装置は、油の圧力を利用して力を伝えたり運動させたりする。","answer":true,"explanation":"パスカルの原理を利用し、ポンプで加圧した作動油でシリンダやモータを駆動します。大きな力を得やすいのが特長です。"},
  {"id":75,"category":"設備保全の基礎","text":"空気圧（空圧）装置では、作動流体として圧縮空気を用いる。","answer":true,"explanation":"空圧は応答が速く扱いやすい反面、油圧に比べ大きな力は出しにくく、圧縮性のため速度制御が難しい面があります。"},
  {"id":76,"category":"設備保全の基礎","text":"締結用のボルト・ナットは、ゆるみが生じても設備の安全性に影響しない。","answer":false,"explanation":"ボルトのゆるみは振動・脱落・破損・事故の原因になります。増し締め、緩み止め（ばね座金・ダブルナット等）、合マーク管理が重要です。"},
  {"id":77,"category":"設備保全の基礎","text":"潤滑不良（油切れ・異物混入）は、軸受や歯車の焼き付き・摩耗の原因になる。","answer":true,"explanation":"油膜が切れると金属同士が接触して発熱・摩耗し、最悪は焼き付きます。適正な油種・油量・清浄度の管理が欠かせません。"},
  {"id":78,"category":"設備保全の基礎","text":"設備の異常は、振動・音・熱・におい・漏れなど五感でも察知できることがある。","answer":true,"explanation":"いつもと違う音や振動、異臭、発熱、油や水の漏れは異常の兆候。日常点検では五感による気づきが早期発見に役立ちます。"},
  {"id":79,"category":"設備保全の基礎","text":"電動機（モータ）の絶縁不良や過熱は、故障や焼損の原因となる。","answer":true,"explanation":"絶縁劣化、過負荷、冷却不良による過熱は巻線の焼損につながります。温度や電流、絶縁抵抗の点検が予防に有効です。"},
  {"id":80,"category":"設備保全の基礎","text":"設備の信頼性を表す指標に、平均故障間隔（MTBF）がある。","answer":true,"explanation":"MTBF（Mean Time Between Failures）は故障と故障の平均間隔で、大きいほど故障しにくい。修理時間の平均はMTTRで表します。"},
  {"id":81,"category":"生産の基本","text":"TPMは、保全部門だけが参加して進める生産保全活動である。","answer":false,"explanation":"TPMは「全員参加」が特徴です。保全部門だけでなく、生産・設計・管理まで全部門・全階層が参加します。"},
  {"id":82,"category":"生産の基本","text":"「整頓」とは、要るものと要らないものを分け、要らないものを捨てることである。","answer":false,"explanation":"それは「整理」の説明です。整頓は、必要なものを使いやすく置き場所・置き方を決めること。整理と整頓の取り違えは頻出の引っかけです。"},
  {"id":83,"category":"生産の基本","text":"5Sの「清潔」とは、床や設備をピカピカに磨き上げる作業そのものを指す。","answer":false,"explanation":"磨く作業は「清掃」です。清潔は、整理・整頓・清掃の3Sが保たれた“状態”を維持することを指します。"},
  {"id":84,"category":"生産の基本","text":"PDCAサイクルのCはChange（変更）を表す。","answer":false,"explanation":"CはCheck（評価・確認）です。計画どおり進んだかを確認する段階を指します。"},
  {"id":85,"category":"生産の基本","text":"三現主義とは「理論・計算・経験」を重んじる考え方である。","answer":false,"explanation":"三現主義は「現場・現物・現実」。机上でなく実際に足を運び、現物を見て、事実で判断する姿勢です。"},
  {"id":86,"category":"生産の基本","text":"QCDのDはDesign（設計）を意味する。","answer":false,"explanation":"DはDelivery（納期）です。QはQuality（品質）、CはCost（コスト）を指します。"},
  {"id":87,"category":"生産の基本","text":"標準作業は、作業者ごとにやり方が変わってよいので特に文書化しなくてよい。","answer":false,"explanation":"標準作業は、最も安全で品質・能率のよい手順を定め、誰がやっても同じ結果になるよう文書化・徹底するものです。"},
  {"id":88,"category":"生産の基本","text":"なぜなぜ分析では、最初に思いついた原因に対策すれば十分である。","answer":false,"explanation":"表面的な原因への対策では再発します。「なぜ」を繰り返して真因にたどり着き、そこに対策を打つのが目的です。"},
  {"id":89,"category":"設備の日常保全","text":"清掃は、汚れを落とすだけの作業で、点検の意味は持たない。","answer":false,"explanation":"「清掃は点検なり」。汚れを取る過程でゆるみ・傷・漏れなどの微欠陥を発見できる、点検を兼ねた活動です。"},
  {"id":90,"category":"設備の日常保全","text":"潤滑油の役割は、摩擦を大きくして部品同士を固定することである。","answer":false,"explanation":"逆です。潤滑は摩擦・摩耗を“減らす”のが第一の役割。ほかに冷却・防錆・密封・洗浄などの働きがあります。"},
  {"id":91,"category":"設備の日常保全","text":"発生源対策より先に、まず汚れを掃除しやすくすることを優先すべきである。","answer":false,"explanation":"最優先は「汚れの発生源を断つ」こと。発生源対策が難しい場合に、飛散防止や清掃しやすくする対策を検討します。"},
  {"id":92,"category":"設備の日常保全","text":"合マークは、ボルトを締める強さ（トルク値）を数値で示すための表示である。","answer":false,"explanation":"合マークは、ナットと相手部材にまたがる線でゆるみ（ずれ）を一目で見つけるための表示です。トルク値を示すものではありません。"},
  {"id":93,"category":"設備の日常保全","text":"異なる油種でも、粘度が同じなら混ぜて使ってよい。","answer":false,"explanation":"油種・銘柄が違う油の混用は、添加剤の反応や性能低下を招くため避けます。指定の油種・粘度を守るのが原則です。"},
  {"id":94,"category":"設備の日常保全","text":"「強制劣化」とは、部品の寿命による避けられない自然な劣化のことである。","answer":false,"explanation":"強制劣化は、清掃・給油・増し締めを怠って“本来防げるのに進めてしまう”人為的な劣化です。これを防ぐのが自主保全の狙いです。"},
  {"id":95,"category":"設備の日常保全","text":"グリースは液状の潤滑剤で、油に比べて飛散しやすい。","answer":false,"explanation":"グリースは半固体状で、むしろ飛散しにくく給油間隔を長くとれるのが特長です。液状なのは潤滑油です。"},
  {"id":96,"category":"設備の日常保全","text":"日常点検は、必ず設備を分解して内部まで確認する点検が中心である。","answer":false,"explanation":"日常点検は運転状態のまま五感で確認するのが中心。分解を伴う点検は定期点検・精密点検で行います。"},
  {"id":97,"category":"効率化とロス","text":"設備総合効率は「時間稼働率 ＋ 性能稼働率 ＋ 良品率」の足し算で求める。","answer":false,"explanation":"足し算ではなく“掛け算”です。時間稼働率×性能稼働率×良品率で求めます。"},
  {"id":98,"category":"効率化とロス","text":"チョコ停は、部品交換や専門修理を要する長時間の停止を指す。","answer":false,"explanation":"チョコ停は数分以内の一時的な小停止・空転で、リセットや詰まり除去ですぐ復旧するもの。修理を要するのは「故障」です。"},
  {"id":99,"category":"効率化とロス","text":"速度低下ロスとは、設備を設計速度より速く動かして生じるロスである。","answer":false,"explanation":"逆です。設計・基準速度より“遅く”動かすことで生じるロスで、性能稼働率を下げます。"},
  {"id":100,"category":"効率化とロス","text":"良品率とは、投入数に対する不良品数の割合のことである。","answer":false,"explanation":"良品率は投入数に対する“良品”数の割合です。不良の割合は不良率で、良品率とは逆の見方になります。"},
  {"id":101,"category":"効率化とロス","text":"チョコ停は一回が短いので、頻発しても設備効率にはほとんど影響しない。","answer":false,"explanation":"一回は短くても頻発すれば累積損失は大きく、性能稼働率を静かに下げます。原因が特定しにくく軽視されがちな重要ロスです。"},
  {"id":102,"category":"効率化とロス","text":"故障には機能停止型しかなく、性能が徐々に落ちる型の故障は存在しない。","answer":false,"explanation":"完全に止まる機能停止型のほか、性能・品質が徐々に落ちる機能低下型があります。後者は気づきにくいのが特徴です。"},
  {"id":103,"category":"効率化とロス","text":"段取り・調整ロスを短くしても、時間稼働率の向上にはつながらない。","answer":false,"explanation":"段取り時間の短縮は停止時間を減らし、時間稼働率を高めます。シングル段取り化などが有効です。"},
  {"id":104,"category":"効率化とロス","text":"稼働率さえ高ければ、不良が多くても設備総合効率は高く保たれる。","answer":false,"explanation":"不良が増えると良品率が下がり、掛け算である設備総合効率も低下します。稼働率だけでは決まりません。"},
  {"id":105,"category":"改善・解析","text":"パレート図は、項目を件数や金額の小さい順に並べるグラフである。","answer":false,"explanation":"パレート図は“大きい順”に並べ、累積曲線とともに重点項目を見つけます。重点指向のための手法です。"},
  {"id":106,"category":"改善・解析","text":"特性要因図は、データのばらつき（分布の形）を把握するための図である。","answer":false,"explanation":"分布を見るのはヒストグラムです。特性要因図は、結果（特性）に対する要因を魚の骨状に整理する図です。"},
  {"id":107,"category":"改善・解析","text":"散布図は、1種類のデータの時間変化を折れ線で示す図である。","answer":false,"explanation":"散布図は“対になった2種類”のデータの相関を点で示す図です。時間変化を見るのは折れ線グラフや管理図です。"},
  {"id":108,"category":"改善・解析","text":"ヒストグラムは、2つのデータの相関関係を調べるために用いる。","answer":false,"explanation":"相関を見るのは散布図です。ヒストグラムは1種類のデータの分布（ばらつきの形）を柱状に表します。"},
  {"id":109,"category":"改善・解析","text":"層別とは、集めたデータをあえて分けずに全体をひとまとめで見る考え方である。","answer":false,"explanation":"層別は逆で、機械別・人別・時間別などに“分けて”解析する考え方です。分けることで問題の所在が見えやすくなります。"},
  {"id":110,"category":"改善・解析","text":"改善の効果は、対策前後を比べなくても実感で判断すればよい。","answer":false,"explanation":"効果は対策前後のデータで定量的に比較します。事実に基づく確認（ファクトコントロール）が基本です。"},
  {"id":111,"category":"改善・解析","text":"ECRSの原則で最初に検討すべきは「Simplify（簡素化）」である。","answer":false,"explanation":"最初はE（Eliminate＝そもそもなくせないか）です。E→C→R→Sの順で、簡素化は最後に検討します。"},
  {"id":112,"category":"改善・解析","text":"改善は思いつきで進めるのが最も早く、データ収集は不要である。","answer":false,"explanation":"事実・データで現状と原因を確認してから対策するのが基本。思いつきの対策は的を外し、再発を招きます。"},
  {"id":113,"category":"設備保全の基礎","text":"時間基準保全（TBM）は、設備の状態を診断して劣化に応じて保全する方式である。","answer":false,"explanation":"それは状態基準保全（CBM）の説明です。TBMは、稼働時間や暦など“一定期間ごと”に点検・交換する方式です。"},
  {"id":114,"category":"設備保全の基礎","text":"予防保全（PM）は、故障してから修理する事後的な保全である。","answer":false,"explanation":"予防保全は故障を“未然に防ぐ”保全。故障してから対応するのは事後保全（BM）です。"},
  {"id":115,"category":"設備保全の基礎","text":"ベアリング（転がり軸受）は、回転部の摩擦を増やして発熱させる部品である。","answer":false,"explanation":"逆です。ベアリングは玉やころの転がりで摩擦を“減らし”、滑らかに回すための部品です。"},
  {"id":116,"category":"設備保全の基礎","text":"改良保全（CM）とは、故障のたびに元どおりに直すだけの保全である。","answer":false,"explanation":"改良保全は、材質や構造を“改善”して故障・劣化そのものを減らす活動。元どおり直すだけとは異なります。"},
  {"id":117,"category":"設備保全の基礎","text":"MTBFは、1回の修理にかかる平均時間を表す指標である。","answer":false,"explanation":"それはMTTR（平均修理時間）です。MTBFは故障と故障の平均間隔で、大きいほど故障しにくいことを示します。"},
  {"id":118,"category":"設備保全の基礎","text":"油圧装置は、空気の圧力を利用して力を伝える装置である。","answer":false,"explanation":"油圧は“作動油（液体）”の圧力を使います。空気（圧縮空気）を使うのは空気圧（空圧）装置です。"},
  {"id":119,"category":"設備保全の基礎","text":"ボルトのゆるみは軽微な現象で、放置しても脱落や事故にはつながらない。","answer":false,"explanation":"ゆるみは振動を増やしさらにゆるみを進め、脱落・破損・事故につながります。増し締めと合マーク管理が重要です。"},
  {"id":120,"category":"設備保全の基礎","text":"保全予防（MP）とは、既存設備が壊れてから対策を考える活動である。","answer":false,"explanation":"保全予防は、設計・計画“段階から”保全しやすく故障しにくい設備をつくる活動。壊れてから考えるものではありません。"},
  {"id":121,"category":"生産の基本","text":"3S活動の3Sとは、整理・整頓・清掃を指す。","answer":true,"explanation":"3Sは整理・整頓・清掃。これに清潔・しつけを加えると5Sになります。"},
  {"id":122,"category":"生産の基本","text":"ムリ・ムラ・ムダの「3ム」は、生産現場で取り除くべき対象とされる。","answer":true,"explanation":"能力を超えたムリ、ばらつきのムラ、価値を生まないムダ。いずれも改善で減らす対象です。"},
  {"id":123,"category":"生産の基本","text":"指差呼称は、対象を指で差し声に出して確認することで、ミスを減らす手法である。","answer":true,"explanation":"「〜ヨシ！」と指差し呼称することで注意力が高まり、確認漏れやヒューマンエラーを減らせます。"},
  {"id":124,"category":"生産の基本","text":"ヒヤリ・ハットは、実際に災害が発生した重大事故だけを記録する。","answer":false,"explanation":"ヒヤリ・ハットは災害に至らなかった“ひやりとした”事例です。集めて未然防止に活かします。"},
  {"id":125,"category":"生産の基本","text":"5W1Hの「Why」は、なぜそれを行うのかという目的・理由を指す。","answer":true,"explanation":"Whyは目的・理由。作業や問題を5W1Hで整理すると、抜け漏れなく伝えられます。"},
  {"id":126,"category":"生産の基本","text":"報告・連絡・相談（報連相）は、円滑な業務遂行のための基本行動である。","answer":true,"explanation":"情報を適切に共有することで、問題の早期発見・対応や連携がスムーズになります。"},
  {"id":127,"category":"生産の基本","text":"作業標準を守ることは、品質や安全のばらつきを抑えることにつながる。","answer":true,"explanation":"決められた最良の手順を全員が守ることで、誰がやっても安定した品質・安全が保てます。"},
  {"id":128,"category":"生産の基本","text":"改善提案は、管理者だけが行うもので、一般オペレーターは対象外である。","answer":false,"explanation":"改善は全員参加が基本。現場をよく知るオペレーターの小さな気づきこそ改善の源泉です。"},
  {"id":129,"category":"生産の基本","text":"PDCAは一度回せば十分で、繰り返す必要はない。","answer":false,"explanation":"PDCAは繰り返し回して“継続的に”改善するための仕組みです。一度で終わりではありません。"},
  {"id":130,"category":"生産の基本","text":"整理・整頓は、安全の確保（つまずき・落下防止など）にも役立つ。","answer":true,"explanation":"通路や置き場が整うと、転倒・落下・接触などの危険が減り、安全性が高まります。"},
  {"id":131,"category":"生産の基本","text":"QCサークルとは、現場の小集団が自主的に品質や改善に取り組む活動である。","answer":true,"explanation":"少人数のグループで、職場の問題を自分たちで見つけて解決していく小集団改善活動です。"},
  {"id":132,"category":"生産の基本","text":"「見える化」は問題を隠すための手法である。","answer":false,"explanation":"逆です。見える化は問題や異常を“表に出して”誰でも気づけるようにし、早期対応につなげる手法です。"},
  {"id":133,"category":"設備の日常保全","text":"増し締めとは、ゆるんだボルト・ナットを規定の強さまで締め直すことである。","answer":true,"explanation":"振動などでゆるんだ締結部を締め直す作業。合マークと組み合わせるとゆるみの発見が容易になります。"},
  {"id":134,"category":"設備の日常保全","text":"給油の「量」は多ければ多いほどよく、入れすぎによる不具合はない。","answer":false,"explanation":"入れすぎは発熱・攪拌抵抗・漏れの原因になります。規定の油面・油量を守ることが大切です。"},
  {"id":135,"category":"設備の日常保全","text":"点検の周期や項目を定めた基準を「暫定基準（仮基準）」として整備することがある。","answer":true,"explanation":"自主保全では、誰でも短時間で確実に守れる清掃・給油・点検の暫定基準をまず作り、改善していきます。"},
  {"id":136,"category":"設備の日常保全","text":"設備の異常の兆候として、いつもと違う「音・振動・におい・熱」がある。","answer":true,"explanation":"五感で感じる変化は異常の重要なサイン。日常点検での気づきが早期発見につながります。"},
  {"id":137,"category":"設備の日常保全","text":"エフ（不具合札）は、見つけた不具合を見える化し、対応を管理するために使う。","answer":true,"explanation":"不具合箇所にエフを付け、処置が済んだら外すことで、微欠陥の摘出と復元を管理します。"},
  {"id":138,"category":"設備の日常保全","text":"清掃困難箇所は、そのまま放置してよく、特に対策は不要である。","answer":false,"explanation":"清掃困難箇所は汚れがたまりやすく劣化の温床です。カバー化や構造改善で清掃しやすくする対策をとります。"},
  {"id":139,"category":"設備の日常保全","text":"潤滑の「五定」には、定油種・定時期・定量などが含まれる。","answer":true,"explanation":"定位置・定油種・定量・定時期・定点検など、正しい潤滑管理のための基本項目です。"},
  {"id":140,"category":"設備の日常保全","text":"油の汚れや水分の混入は、潤滑性能を低下させ設備トラブルの原因になる。","answer":true,"explanation":"異物や水分は油膜を破り、摩耗・さび・焼き付きを招きます。給油口やタンクの清浄管理が重要です。"},
  {"id":141,"category":"設備の日常保全","text":"点検口や給油口を1か所に集約すると、点検・給油の手間と見落としが減る。","answer":true,"explanation":"分散した点検・給油箇所を集約（一元化）すると、短時間で確実に作業でき、抜けが減ります。"},
  {"id":142,"category":"設備の日常保全","text":"油面計・圧力計などの計器には、正常範囲を示す表示を付けると管理しやすい。","answer":true,"explanation":"正常範囲を色分けやラインで表示すると、正常・異常を一目で判断でき、目で見る管理になります。"},
  {"id":143,"category":"設備の日常保全","text":"清掃で発見した微欠陥は、小さいものであれば記録も対応も不要である。","answer":false,"explanation":"微欠陥は放置すると強制劣化や故障につながります。小さくてもエフを付けて記録・処置します。"},
  {"id":144,"category":"設備の日常保全","text":"自主保全のステップ活動では、まず初期清掃から着手するのが一般的である。","answer":true,"explanation":"第1ステップの初期清掃で設備に触れ、微欠陥や発生源を洗い出すことから活動が始まります。"},
  {"id":145,"category":"設備の日常保全","text":"ベルトやチェーンの張り具合の点検も、日常保全の項目に含まれる。","answer":true,"explanation":"張りすぎ・緩みすぎは摩耗や振動、すべりの原因になります。適正な張力の点検・調整が必要です。"},
  {"id":146,"category":"設備の日常保全","text":"設備の清掃は、電源を入れた稼働中に手を入れて行うのが基本である。","answer":false,"explanation":"回転部・可動部の清掃は原則停止・電源遮断（安全確保）してから行います。稼働中の手入れは危険です。"},
  {"id":147,"category":"設備の日常保全","text":"空圧機器のドレン（たまった水）は、放置せず定期的に抜く必要がある。","answer":true,"explanation":"ドレンを放置すると機器の不調やさびの原因になります。定期的な排出が日常保全の一部です。"},
  {"id":148,"category":"設備の日常保全","text":"給油に使う油差しやグリースガンは、汚れていても性能に影響しない。","answer":false,"explanation":"給油器具が汚れていると異物を油と一緒に注入してしまいます。器具の清浄管理も重要です。"},
  {"id":149,"category":"設備の日常保全","text":"設備の基本条件（清掃・給油・増し締め）を保つことは、故障の未然防止につながる。","answer":true,"explanation":"基本条件を整えることで劣化の進行を抑え、突発故障を減らせます。自主保全の土台です。"},
  {"id":150,"category":"設備の日常保全","text":"点検基準は一度決めたら、その後見直してはならない。","answer":false,"explanation":"点検基準は活動や設備状況に応じて見直し、より確実で効率的なものに改善していきます。"},
  {"id":151,"category":"設備の日常保全","text":"温度の異常を調べる際、非接触の放射温度計を使うことができる。","answer":true,"explanation":"回転部や高温部など触れられない箇所の温度を、放射温度計で安全に測定できます。"},
  {"id":152,"category":"設備の日常保全","text":"清掃・給油・点検の項目や周期を、誰が見てもわかる形にしておくのが望ましい。","answer":true,"explanation":"基準を見える化し標準化することで、担当が替わっても同じ品質で保全を続けられます。"},
  {"id":153,"category":"効率化とロス","text":"段取り替えや調整に要する時間は、段取り・調整ロスとして扱われる。","answer":true,"explanation":"生産を止めて行う段取り替えや調整の時間は、7大ロスの一つとして時間稼働率を下げます。"},
  {"id":154,"category":"効率化とロス","text":"刃具（工具）の交換に伴う停止も、設備効率を阻害するロスに含まれる。","answer":true,"explanation":"刃具交換ロスは7大ロスの一つ。工具の摩耗・破損による交換のための停止です。"},
  {"id":155,"category":"効率化とロス","text":"時間稼働率は、負荷時間に対する稼働時間の割合で表される。","answer":true,"explanation":"時間稼働率＝稼働時間÷負荷時間。停止ロスが少ないほど高くなります。"},
  {"id":156,"category":"効率化とロス","text":"設備総合効率を高めるには、良品率を無視して稼働率だけ上げればよい。","answer":false,"explanation":"設備総合効率は3要素の掛け算。良品率が低ければ全体も下がるため、バランスが必要です。"},
  {"id":157,"category":"効率化とロス","text":"立上りロスは、生産終了時の後片付けで生じるロスのことである。","answer":false,"explanation":"立上りロスは、始業時や段取り替え後、生産が安定するまでに生じるロスです。後片付けではありません。"},
  {"id":158,"category":"効率化とロス","text":"TPMでは、設備・人・原単位に分けてロスを体系的に捉える。","answer":true,"explanation":"16大ロスとして、設備の効率を阻害するロス、人の効率のロス、原単位（材料・エネルギー）のロスを整理します。"},
  {"id":159,"category":"効率化とロス","text":"性能稼働率は、速度に関するロス（速度低下・チョコ停）を反映する。","answer":true,"explanation":"基準サイクルタイムに対する実速度・小停止を反映するのが性能稼働率です。"},
  {"id":160,"category":"効率化とロス","text":"ロスを金額換算すると、改善の効果や優先度を経営的に判断しやすくなる。","answer":true,"explanation":"ロスコストとして金額で示すと、どこを改善すべきか、いくら得られるかが判断しやすくなります。"},
  {"id":161,"category":"効率化とロス","text":"チョコ停は、原因が明確で対策も容易なため、放置してよいロスである。","answer":false,"explanation":"チョコ停は原因が特定しにくく頻発するため、放置は禁物。累積すると大きな損失になります。"},
  {"id":162,"category":"効率化とロス","text":"不良品を手直しして良品にする作業も、ロス（手直しロス）に含まれる。","answer":true,"explanation":"手直しには余分な時間・材料がかかり、良品率や効率を下げるロスとして扱います。"},
  {"id":163,"category":"効率化とロス","text":"設備が停止していなくても、速度が落ちていればロスは発生している。","answer":true,"explanation":"速度低下ロスのように、動いていても本来速度より遅ければ、その差がロスになります。"},
  {"id":164,"category":"効率化とロス","text":"負荷時間とは、暦時間から生産計画上の休止時間を除いた、動かすべき時間である。","answer":true,"explanation":"負荷時間は設備を稼働させる予定の時間。ここから停止ロスを引くと稼働時間になります。"},
  {"id":165,"category":"改善・解析","text":"管理図で点が管理限界線を超えたら、工程に異常がある可能性を疑う。","answer":true,"explanation":"限界線超えや点の並びの癖は、偶然でないばらつき（異常原因）のサインとして調査します。"},
  {"id":166,"category":"改善・解析","text":"グラフは、目的（大小・変化・割合など）に応じて種類を使い分けるとよい。","answer":true,"explanation":"棒グラフは大小、折れ線は変化、円グラフは割合など、伝えたい内容で選びます。"},
  {"id":167,"category":"改善・解析","text":"「歯止め」とは、改善効果を維持するために標準化・仕組み化することである。","answer":true,"explanation":"改善が元に戻らないよう、作業標準や点検基準に反映して定着させることを歯止めといいます。"},
  {"id":168,"category":"改善・解析","text":"QC七つ道具は、主に数値（計量・計数）データを扱う手法群である。","answer":true,"explanation":"パレート図やヒストグラムなど数値データ中心。言語データは新QC七つ道具で扱います。"},
  {"id":169,"category":"改善・解析","text":"特性要因図の「特性」とは、解決したい結果（不良や故障など）を指す。","answer":true,"explanation":"特性＝結果。その結果を生む要因を大骨・小骨に整理して原因を探ります。"},
  {"id":170,"category":"改善・解析","text":"改善は、効果のあった対策でも標準化しなければ元に戻ることがある。","answer":true,"explanation":"歯止め（標準化）をしないと、時間とともに元のやり方に戻ってしまいがちです。"},
  {"id":171,"category":"改善・解析","text":"パレート図の累積曲線は、上位項目が全体に占める割合を読み取るのに役立つ。","answer":true,"explanation":"累積曲線から「上位数項目で全体の大半を占める」ことがわかり、重点対象を選べます。"},
  {"id":172,"category":"改善・解析","text":"データを取る前に、何を目的にどう分けて集めるか（層別）を考えるとよい。","answer":true,"explanation":"あらかじめ層別の視点を決めておくと、後から原因を切り分けやすくなります。"},
  {"id":173,"category":"改善・解析","text":"散布図で右上がりの傾向が見えるとき、2つの量には正の相関がある。","answer":true,"explanation":"一方が増えるともう一方も増える関係が正の相関。右上がりの点の広がりで判断します。"},
  {"id":174,"category":"改善・解析","text":"改善活動では、対策後の効果確認を省略してよい。","answer":false,"explanation":"効果確認は必須です。狙いどおり改善したかをデータで確かめ、不十分なら再検討します。"},
  {"id":175,"category":"改善・解析","text":"チェックシートは、記録と同時にどこに問題が集中しているか把握しやすい。","answer":true,"explanation":"項目ごとにチェックを集計する形なので、集中箇所や傾向がその場で見えてきます。"},
  {"id":176,"category":"改善・解析","text":"問題解決では、現象への対処より真因への対策を優先すべきである。","answer":true,"explanation":"現象だけ抑えても再発します。なぜなぜ分析などで真因を突き止め、そこに対策を打ちます。"},
  {"id":177,"category":"設備保全の基礎","text":"すべり軸受は、油膜を介して軸を支える構造の軸受である。","answer":true,"explanation":"すべり軸受は軸と軸受の間の油膜で支えます。転がり軸受（ベアリング）とは支持方式が異なります。"},
  {"id":178,"category":"設備保全の基礎","text":"歯車の潤滑が不十分だと、摩耗や歯の欠けの原因になる。","answer":true,"explanation":"潤滑不良は金属接触による摩耗・発熱・欠損を招きます。適正な給油が寿命を左右します。"},
  {"id":179,"category":"設備保全の基礎","text":"チェーンは、スプロケットとかみ合って動力を伝える伝動要素である。","answer":true,"explanation":"ローラチェーンなどがスプロケット（歯車）とかみ合い、すべりなく動力を伝えます。"},
  {"id":180,"category":"設備保全の基礎","text":"カップリング（軸継手）は、2本の軸を連結して回転を伝える部品である。","answer":true,"explanation":"モータ軸と機械軸などを連結。芯ずれを吸収するタイプもあり、芯出し不良は振動・破損の原因です。"},
  {"id":181,"category":"設備保全の基礎","text":"ポンプは、液体などの流体を移送・加圧するための機械である。","answer":true,"explanation":"羽根車や容積変化で流体にエネルギーを与え、送り出したり圧力を高めたりします。"},
  {"id":182,"category":"設備保全の基礎","text":"電動機（モータ）は、電気エネルギーを機械的な回転力に変換する。","answer":true,"explanation":"電気を受けて回転力を生み出す機械。過負荷や絶縁劣化による過熱・焼損に注意が必要です。"},
  {"id":183,"category":"設備保全の基礎","text":"ヒューズやブレーカは、過電流から回路や機器を守るための保護部品である。","answer":true,"explanation":"規定を超える電流が流れると回路を遮断し、機器の焼損や火災を防ぎます。"},
  {"id":184,"category":"設備保全の基礎","text":"接地（アース）は、感電や機器故障を防ぐための安全対策である。","answer":true,"explanation":"漏電時に電流を大地へ逃がし、感電や機器の損傷を防ぎます。電気安全の基本です。"},
  {"id":185,"category":"設備保全の基礎","text":"ボルトの締結には、ばね座金などのゆるみ止め部品が使われることがある。","answer":true,"explanation":"ばね座金・ダブルナット・ゆるみ止め剤などで、振動によるゆるみを防ぎます。"},
  {"id":186,"category":"設備保全の基礎","text":"油圧回路のリリーフ弁は、回路の圧力が上がりすぎないよう逃がす役割を持つ。","answer":true,"explanation":"設定圧を超えると油を逃がして最高圧を制限し、機器や配管を保護します。"},
  {"id":187,"category":"設備保全の基礎","text":"空気圧装置は、油圧に比べて大きな力を出すのが得意である。","answer":false,"explanation":"逆です。大きな力は油圧が得意。空圧は応答が速く扱いやすい反面、大出力には向きません。"},
  {"id":188,"category":"設備保全の基礎","text":"作動油の温度が高くなりすぎると、油の劣化や機器不調の原因になる。","answer":true,"explanation":"油温上昇は粘度低下・酸化劣化・シール劣化を招きます。冷却や油量管理が必要です。"},
  {"id":189,"category":"設備保全の基礎","text":"図面の寸法公差は、許容される寸法のばらつきの範囲を示す。","answer":true,"explanation":"公差は「この範囲内なら合格」という許容差。加工や部品選定の基準になります。"},
  {"id":190,"category":"設備保全の基礎","text":"「ねじのピッチ」とは、隣り合うねじ山の間隔のことである。","answer":true,"explanation":"ピッチはねじ山の間隔。合わないボルト・ナットは締結できず、破損の原因にもなります。"},
  {"id":191,"category":"設備保全の基礎","text":"振動計や温度計による測定は、状態基準保全（CBM）の判断に役立つ。","answer":true,"explanation":"振動・温度などの状態を測って劣化を把握し、必要なときに保全するのがCBMです。"},
  {"id":192,"category":"設備保全の基礎","text":"設備の劣化を放置すると、突発故障や品質不良のリスクが高まる。","answer":true,"explanation":"劣化の進行は故障や不良に直結します。早期発見・早期処置が損失を防ぎます。"},
  {"id":193,"category":"設備保全の基礎","text":"MTTRは、平均修理時間（故障からの復旧にかかる平均時間）を表す。","answer":true,"explanation":"MTTR（Mean Time To Repair）。小さいほど早く復旧でき、保全性が高いことを示します。"},
  {"id":194,"category":"設備保全の基礎","text":"保全性とは、故障した設備をいかに早く・容易に修復できるかを表す性質である。","answer":true,"explanation":"保全のしやすさ・復旧の速さを表す性質。MTTRなどで評価されます。"},
  {"id":195,"category":"設備保全の基礎","text":"信頼性の高い設備とは、故障しにくく安定して稼働できる設備のことである。","answer":true,"explanation":"故障の少なさ（MTBFの大きさ）などで表され、安定稼働につながります。"},
  {"id":196,"category":"設備保全の基礎","text":"Oリングやオイルシールは、油や空気の漏れを防ぐ密封部品である。","answer":true,"explanation":"すきまを密封して流体の漏れや異物侵入を防ぎます。劣化すると漏れの原因になります。"},
  {"id":197,"category":"設備保全の基礎","text":"軸受の異常は、異音・発熱・振動として現れることがある。","answer":true,"explanation":"潤滑不良や損傷が進むと、異音・発熱・振動が生じます。早期の点検・交換が重要です。"},
  {"id":198,"category":"設備保全の基礎","text":"配管のバルブ（弁）は、流体の流れを止めたり量を調整したりする部品である。","answer":true,"explanation":"開閉や絞りで流量・圧力を制御します。種類により用途（開閉用・調整用）が異なります。"},
  {"id":199,"category":"設備保全の基礎","text":"電気配線の被覆が傷むと、漏電や短絡（ショート）の危険がある。","answer":true,"explanation":"被覆の損傷・劣化は絶縁不良を招き、漏電・短絡・火災の原因になります。点検が必要です。"},
  {"id":200,"category":"設備保全の基礎","text":"予備品（スペアパーツ）を適切に管理することは、故障時の早期復旧に役立つ。","answer":true,"explanation":"必要な予備品を在庫・管理しておくと、故障時にすぐ交換でき、停止時間を短縮できます。"},
  {"id":201,"category":"生産の基本","text":"保護めがねや安全靴などの保護具は、危険を完全になくすための第一の対策である。","answer":false,"explanation":"対策の優先順位は「本質安全化→工学的対策→管理的対策→保護具」。保護具は最後の手段で、まず危険源そのものを除去します。"},
  {"id":202,"category":"生産の基本","text":"リスクアセスメントとは、危険の大きさを見積もり、優先順位をつけて対策する手法である。","answer":true,"explanation":"危険性・有害性を洗い出し、重篤度と発生可能性からリスクを見積もって、優先度の高いものから低減します。"},
  {"id":203,"category":"生産の基本","text":"設備の点検・修理で他の人が誤って電源を入れないよう、施錠して札を掛ける手順をロックアウト・タグアウトという。","answer":true,"explanation":"作業中の不意の起動を防ぐ安全手順。電源を切るだけでなく施錠と表示で第三者の操作を物理的に防ぎます。"},
  {"id":204,"category":"生産の基本","text":"ハインリッヒの法則では、1件の重大災害の背後に多数の軽傷・ヒヤリハットがあるとされる。","answer":true,"explanation":"1:29:300の比率で知られ、軽微な事象の段階で対策することが重大災害の防止につながるという考え方です。"},
  {"id":205,"category":"生産の基本","text":"5Sの「しつけ」とは、決めたルールを守る習慣を身につけることである。","answer":true,"explanation":"整理・整頓・清掃・清潔を継続できるよう、教育と習慣化で定着させる段階です。"},
  {"id":206,"category":"生産の基本","text":"OJTとは、職場を離れて研修施設などで学ぶ教育方法のことである。","answer":false,"explanation":"OJT（On the Job Training）は職場で実務を通じて指導する方法。職場を離れる研修はOFF-JTです。"},
  {"id":207,"category":"生産の基本","text":"スキルマップ（力量表）は、誰が何をどの程度できるかを見える化する表である。","answer":true,"explanation":"作業ごとの習熟度を一覧化し、教育計画や多能工化の推進、要員配置の判断に使います。"},
  {"id":208,"category":"生産の基本","text":"多能工化とは、一人の作業者が複数の工程・作業をこなせるようにすることである。","answer":true,"explanation":"欠員や生産変動に柔軟に対応でき、応援体制やライン編成の自由度が高まります。"},
  {"id":209,"category":"生産の基本","text":"省エネルギー活動は、コスト削減だけでなく環境負荷の低減にもつながる。","answer":true,"explanation":"エネルギー使用量の削減はCO2排出削減にも直結し、原単位ロスの低減としてTPMの対象にもなります。"},
  {"id":210,"category":"生産の基本","text":"廃棄物の分別は、リサイクル率の向上や処理コストの低減に役立つ。","answer":true,"explanation":"適切な分別により再資源化が進み、埋立・焼却量が減って処理費用も下がります。"},
  {"id":211,"category":"生産の基本","text":"直接材料費や直接労務費は、製品の製造原価に含まれる。","answer":true,"explanation":"製造原価は材料費・労務費・経費で構成されます。ロス削減は原価低減に直結します。"},
  {"id":212,"category":"生産の基本","text":"生産計画とは、何を・いつ・どれだけ作るかを決めることである。","answer":true,"explanation":"需要に対して人・設備・材料をどう配分するかを計画し、納期と稼働の安定を図ります。"},
  {"id":213,"category":"生産の基本","text":"作業手順書は、新人でも同じ品質で作業できるようにするための文書である。","answer":true,"explanation":"手順・条件・急所（ポイント）を明記し、誰がやっても安全で同じ結果になるようにします。"},
  {"id":214,"category":"生産の基本","text":"「急所」とは、作業手順のうち、品質・安全・やりやすさを左右する重要な勘どころを指す。","answer":true,"explanation":"手順だけでなく「なぜそうするか」の急所を伝えることが、教育の要点です。"},
  {"id":215,"category":"生産の基本","text":"整理・整頓の「赤札作戦」とは、不要品に赤い札を付けて処分の判断をする活動である。","answer":true,"explanation":"要否の判断を見える化し、期限を決めて処分・移動することで職場をすっきりさせます。"},
  {"id":216,"category":"生産の基本","text":"KYT（危険予知訓練）は、作業後に反省会として行うのが基本である。","answer":false,"explanation":"KYTは作業「前」に危険を予知して対策と行動目標を決める活動。事後の反省会ではありません。"},
  {"id":217,"category":"生産の基本","text":"5Sは、品質・安全・効率のすべての土台となる活動である。","answer":true,"explanation":"職場が整うと異常が見えやすくなり、ムダ・事故・不良が減ります。改善活動の出発点です。"},
  {"id":218,"category":"生産の基本","text":"「見える化」の例として、あんどん（異常表示灯）が挙げられる。","answer":true,"explanation":"異常が起きるとランプで知らせ、誰でもすぐ気づいて対応できるようにする代表的な手法です。"},
  {"id":219,"category":"生産の基本","text":"作業改善では、まず現状の作業を観察・記録して事実を把握することが出発点となる。","answer":true,"explanation":"思い込みでなく現状の事実（時間・動作・回数）を掴むことで、ムダの所在が見えてきます。"},
  {"id":220,"category":"生産の基本","text":"労働災害を防ぐには、設備の安全化よりも作業者の注意力に頼るほうが確実である。","answer":false,"explanation":"人は必ずミスをします。注意喚起だけに頼らず、設備側で危険を除去する本質安全化が優先です。"},
  {"id":221,"category":"設備の日常保全","text":"自主保全の第2ステップは、発生源・困難箇所対策である。","answer":true,"explanation":"第1ステップの初期清掃で見つけた汚れの発生源を断ち、清掃・給油しにくい箇所を改善します。"},
  {"id":222,"category":"設備の日常保全","text":"自主保全の第3ステップでは、清掃・給油の暫定基準を作成する。","answer":true,"explanation":"誰でも短時間で確実に維持できる基準を自分たちで作り、守れる形にしていきます。"},
  {"id":223,"category":"設備の日常保全","text":"自主保全の最終段階では、オペレーター自らが設備を管理し改善を続ける状態を目指す。","answer":true,"explanation":"自主管理の徹底が目標。決められたことを守るだけでなく、自ら考えて改善できる人と職場を育てます。"},
  {"id":224,"category":"設備の日常保全","text":"総点検教育では、設備の構造や機能を学び、オペレーターの点検技能を高める。","answer":true,"explanation":"機械・電気・潤滑などの基礎を学び、異常を見つけられる目を養う段階です。"},
  {"id":225,"category":"設備の日常保全","text":"スパナやレンチは、押して使うより引いて使うほうが安全である。","answer":true,"explanation":"押すと外れた際に手をぶつけやすく危険。引く方向で力をかけるのが基本です。"},
  {"id":226,"category":"設備の日常保全","text":"トルクレンチは、ボルトを規定の締付力（トルク）で締めるための工具である。","answer":true,"explanation":"締めすぎ・締め不足を防ぎ、適正な締結力を確保します。設定値の管理も重要です。"},
  {"id":227,"category":"設備の日常保全","text":"ボルトは強く締めれば締めるほどよく、締めすぎによる不具合はない。","answer":false,"explanation":"締めすぎはねじの伸び・破断や部材の変形を招きます。規定トルクを守ることが必要です。"},
  {"id":228,"category":"設備の日常保全","text":"設備の異常を発見したら、自分で判断せず勝手に分解・修理してよい。","answer":false,"explanation":"権限や技能の範囲を超える処置は危険です。決められた手順に従い、報告・連絡して対応します。"},
  {"id":229,"category":"設備の日常保全","text":"異常の「予兆」を早期に捉えることは、突発故障の防止につながる。","answer":true,"explanation":"わずかな異音・振動・発熱・漏れの変化を捉えて手を打てば、大きな故障を未然に防げます。"},
  {"id":230,"category":"設備の日常保全","text":"点検で「異常なし」が続いたら、その点検項目はやめてよい。","answer":false,"explanation":"異常なしが続くのは点検と保全が効いている証拠です。やめると劣化の進行を見逃すため、継続が必要です。"},
  {"id":231,"category":"設備の日常保全","text":"チェーンやベルトの給油は、回転を止めてから行うのが安全である。","answer":true,"explanation":"回転中の給油は巻き込まれの危険があります。必ず停止・電源遮断してから行います。"},
  {"id":232,"category":"設備の日常保全","text":"設備の周囲に工具や部品を置きっぱなしにすると、巻き込みや転倒の原因になる。","answer":true,"explanation":"整理・整頓は安全の基本。可動部への落下や作業者のつまずきを防ぎます。"},
  {"id":233,"category":"設備の日常保全","text":"清掃用のウエス（布）は、油が染みたものでも放置してよい。","answer":false,"explanation":"油の染みたウエスは自然発火や火災の原因になります。専用容器に入れて適切に処理します。"},
  {"id":234,"category":"設備の日常保全","text":"自主保全活動では、活動板（見える化ボード）で進捗や成果を共有することがある。","answer":true,"explanation":"エフの摘出数や改善件数を掲示し、メンバーの意識と活動の継続を支えます。"},
  {"id":235,"category":"設備の日常保全","text":"設備の「ワンポイントレッスン（OPL）」は、1枚の紙で1テーマを短時間で学ぶ教材である。","answer":true,"explanation":"基本知識やトラブル事例、改善事例を1枚にまとめ、朝礼などで短時間に共有します。"},
  {"id":236,"category":"設備の日常保全","text":"給油ラベルや点検ラベルを貼ることは、作業の抜け漏れを防ぐのに有効である。","answer":true,"explanation":"どこに何をいつ行うかを現物に表示することで、誰でも確実に実施できます。"},
  {"id":237,"category":"設備の日常保全","text":"日常点検の記録は、後から傾向を分析するための貴重なデータになる。","answer":true,"explanation":"温度や振動の推移を残すことで、劣化の進行や異常の兆候を早期に把握できます。"},
  {"id":238,"category":"設備の日常保全","text":"設備の防錆対策として、清掃後に適切な油膜を残すことが有効な場合がある。","answer":true,"explanation":"水分や湿気による発錆を防ぐため、必要に応じて防錆油や適正な油膜を維持します。"},
  {"id":239,"category":"設備の日常保全","text":"フィルタの目詰まりは、流量低下や機器の過熱・故障の原因になる。","answer":true,"explanation":"油圧・空圧・冷却系のフィルタが詰まると性能が落ち、機器を傷めます。定期交換が必要です。"},
  {"id":240,"category":"設備の日常保全","text":"配管の継手やホースからの漏れは、放置しても設備性能に影響しない。","answer":false,"explanation":"漏れは圧力・流量の低下、油量不足、汚染、滑りによる転倒災害の原因になります。早期処置が必要です。"},
  {"id":241,"category":"効率化とロス","text":"歩留まりとは、投入した原材料に対して得られた製品の割合のことである。","answer":true,"explanation":"歩留まりが低いと材料のムダが大きい。原単位ロスの重要な指標です。"},
  {"id":242,"category":"効率化とロス","text":"タクトタイムとは、製品1個を作るのに許される時間（需要に基づく）である。","answer":true,"explanation":"稼働時間÷必要生産数で求め、この時間内に工程を収めるようライン編成します。"},
  {"id":243,"category":"効率化とロス","text":"サイクルタイムとは、実際に1個を作るのにかかっている時間のことである。","answer":true,"explanation":"サイクルタイムがタクトタイムを超えると納期に間に合いません。両者の比較が改善の起点です。"},
  {"id":244,"category":"効率化とロス","text":"ボトルネック工程とは、全体の流れを最も制約している工程のことである。","answer":true,"explanation":"最も時間のかかる工程が全体の生産能力を決めます。ここを改善しないと全体は速くなりません。"},
  {"id":245,"category":"効率化とロス","text":"ラインバランスとは、各工程の作業時間のばらつきを均す考え方である。","answer":true,"explanation":"工程間の時間差を小さくすることで、待ちや手待ちのムダを減らせます。"},
  {"id":246,"category":"効率化とロス","text":"仕掛品（中間在庫）が多いことは、常に良いことである。","answer":false,"explanation":"過剰な仕掛品は場所・資金を占有し、不良の発見を遅らせます。「造りすぎのムダ」の典型です。"},
  {"id":247,"category":"効率化とロス","text":"7つのムダには、造りすぎ・手待ち・運搬・加工そのもの・在庫・動作・不良のムダが含まれる。","answer":true,"explanation":"トヨタ生産方式で整理されたムダの分類で、改善の着眼点として広く使われます。"},
  {"id":248,"category":"効率化とロス","text":"「造りすぎのムダ」は、他のムダを生み出す元凶とされる。","answer":true,"explanation":"必要以上に作ると在庫・運搬・手待ちなど他のムダを誘発するため、最も重視されます。"},
  {"id":249,"category":"効率化とロス","text":"工程能力指数（Cp・Cpk）は、工程が規格を満たす能力を数値で表す。","answer":true,"explanation":"ばらつきと規格幅の関係を示し、値が大きいほど規格内に安定して収まる能力が高いことを意味します。"},
  {"id":250,"category":"効率化とロス","text":"品質は検査で作り込むものであり、工程で作り込む必要はない。","answer":false,"explanation":"「品質は工程で作り込む」が原則。検査は選別にすぎず、工程条件の管理で不良を出さないことが本質です。"},
  {"id":251,"category":"効率化とロス","text":"ポカヨケとは、人がうっかりミスをしても不良や事故が起きないようにする仕組みである。","answer":true,"explanation":"間違った向きでは入らない、抜けがあると次に進めない、などの工夫でヒューマンエラーを防ぎます。"},
  {"id":252,"category":"効率化とロス","text":"抜取検査は、全数検査に比べて検査工数を減らせるが、不良の見逃しリスクがある。","answer":true,"explanation":"ロットから一部を抜き取って判定する方法で、コストとリスクのバランスで選択します。"},
  {"id":253,"category":"効率化とロス","text":"不良の「流出」とは、不良品が後工程や顧客に渡ってしまうことである。","answer":true,"explanation":"発生の防止（作らない）と流出の防止（出さない）の両面で対策します。"},
  {"id":254,"category":"効率化とロス","text":"設備の空転（アイドリング）も、性能を阻害するロスに数えられる。","answer":true,"explanation":"チョコ停・空転ロスとして、設備が動いているのに生産していない時間を損失と捉えます。"},
  {"id":255,"category":"効率化とロス","text":"1個流し（一個流し生産）は、まとめ作りに比べて不良の早期発見に有利である。","answer":true,"explanation":"1個ごとに次工程へ渡すため、不良が出てもすぐ気づけ、被害を最小に抑えられます。"},
  {"id":256,"category":"効率化とロス","text":"標準時間とは、決められた方法・条件で作業を行うのに必要な時間のことである。","answer":true,"explanation":"能率の評価や工数見積もり、ライン編成の基礎になる時間です。"},
  {"id":257,"category":"効率化とロス","text":"稼働分析では、作業時間のうち付加価値を生んでいる割合を把握できる。","answer":true,"explanation":"正味作業・付随作業・ムダを分けて観察し、改善の的を絞ります。"},
  {"id":258,"category":"効率化とロス","text":"設備の総合効率が低い原因を特定するには、ロスを分解して見ることが有効である。","answer":true,"explanation":"停止・速度・不良のどこで落ちているかを分けて見ると、打つべき手が明確になります。"},
  {"id":259,"category":"効率化とロス","text":"シングル段取りとは、段取り替えを10分未満で完了させることを目指す考え方である。","answer":true,"explanation":"「1桁分（シングル）」の時間に収める改善。内段取りを外段取り化するのが要点です。"},
  {"id":260,"category":"効率化とロス","text":"内段取りとは、設備を止めなければできない段取り作業のことである。","answer":true,"explanation":"設備を止めずにできる外段取りへ移すことで、停止時間を短縮できます。"},
  {"id":261,"category":"改善・解析","text":"新QC七つ道具は、主に言語データ（意見・アイデア）を整理するのに使う。","answer":true,"explanation":"親和図法・連関図法・系統図法など、数値化しにくい情報を構造化する手法群です。"},
  {"id":262,"category":"改善・解析","text":"親和図法は、バラバラの意見をグループにまとめて問題の全体像をつかむ手法である。","answer":true,"explanation":"言語データを似たもの同士で束ね、隠れた構造や本質的な課題を浮かび上がらせます。"},
  {"id":263,"category":"改善・解析","text":"特性要因図は、原因を洗い出す手法であり、対策の優先順位までは示さない。","answer":true,"explanation":"要因を網羅的に整理するのが目的。どれが真因か・どれから手を付けるかは別途データで検証します。"},
  {"id":264,"category":"改善・解析","text":"IE（インダストリアル・エンジニアリング）は、作業や工程のムダを分析して改善する技術である。","answer":true,"explanation":"動作研究・時間研究などにより、作業方法や工程配置を科学的に改善します。"},
  {"id":265,"category":"改善・解析","text":"動作経済の原則では、両手を同時に使う、動作距離を短くするなどが推奨される。","answer":true,"explanation":"人の動きのムダを減らす原則。疲労を抑えつつ作業速度と安定性を高めます。"},
  {"id":266,"category":"改善・解析","text":"VE（バリュー・エンジニアリング）では、価値＝機能÷コストで考える。","answer":true,"explanation":"機能を落とさずコストを下げる、または同じコストで機能を高めることで価値を向上させます。"},
  {"id":267,"category":"改善・解析","text":"VEでは、まず「その部品は何のためにあるのか（機能）」を問うことから始める。","answer":true,"explanation":"機能本位で考えることで、形にとらわれない抜本的な改善案が生まれます。"},
  {"id":268,"category":"改善・解析","text":"工程分析では、加工・検査・運搬・停滞などの記号を使って流れを表す。","answer":true,"explanation":"工程図記号で流れを可視化すると、運搬や停滞のムダが一目でわかります。"},
  {"id":269,"category":"改善・解析","text":"時間研究（タイムスタディ）は、作業時間を測定して標準時間を求める手法である。","answer":true,"explanation":"作業を要素に分けて測定し、余裕率を加味して標準時間を設定します。"},
  {"id":270,"category":"改善・解析","text":"QCストーリーは、テーマ選定から効果確認・歯止めまでを順に進める問題解決の型である。","answer":true,"explanation":"現状把握→目標設定→要因解析→対策立案→実施→効果確認→標準化、という手順で進めます。"},
  {"id":271,"category":"改善・解析","text":"QCストーリーでは、対策を実施した後で現状把握を行うのが正しい順序である。","answer":false,"explanation":"現状把握は対策の「前」です。事実を掴んでから目標を決め、要因を解析して対策します。"},
  {"id":272,"category":"改善・解析","text":"目標設定では、いつまでに・何を・どれだけ、を数値で明確にすることが望ましい。","answer":true,"explanation":"数値目標があると効果測定ができ、達成・未達の判断と次の一手が明確になります。"},
  {"id":273,"category":"改善・解析","text":"ブレーンストーミングでは、他人のアイデアを批判せず、量を多く出すことが重視される。","answer":true,"explanation":"批判厳禁・自由奔放・質より量・便乗歓迎の4原則で、発想を広げます。"},
  {"id":274,"category":"改善・解析","text":"改善の効果は、金額（コスト削減額）で表すと経営層に伝わりやすい。","answer":true,"explanation":"時間短縮や不良削減を金額換算することで、改善の価値が共通言語で伝わります。"},
  {"id":275,"category":"改善・解析","text":"PM分析は、故障やチョコ停の原因を物理的に解析し、成立条件を洗い出す手法である。","answer":true,"explanation":"現象を物理的に捉え、その現象が成立する条件をすべて挙げて対策する、慢性ロス向けの手法です。"},
  {"id":276,"category":"改善・解析","text":"慢性的なロスは、原因が複合していることが多く、単純な対策では解決しにくい。","answer":true,"explanation":"複数の要因が絡むため、PM分析などで成立条件を漏れなく洗い出す必要があります。"},
  {"id":277,"category":"改善・解析","text":"データを取る際は、いつ・どこで・誰が・どんな条件で取ったかを記録しておくとよい。","answer":true,"explanation":"条件が分からないデータは解析に使えません。層別できるよう属性を併せて記録します。"},
  {"id":278,"category":"改善・解析","text":"改善案は、効果の大きさと実施の容易さの両面から評価して選ぶとよい。","answer":true,"explanation":"効果が大きく実施しやすい案から着手すると、早く成果が出て活動が続きます。"},
  {"id":279,"category":"改善・解析","text":"5W1Hの「Why」を繰り返すことは、なぜなぜ分析の考え方に通じる。","answer":true,"explanation":"目的や原因を問い直すことで、表面的でない本質的な改善につながります。"},
  {"id":280,"category":"改善・解析","text":"改善活動の成果は、当事者だけが知っていればよく、他部署に共有する必要はない。","answer":false,"explanation":"水平展開により、似た設備・工程での同様の問題を未然に防げます。共有は重要です。"},
  {"id":281,"category":"設備保全の基礎","text":"リレー（電磁継電器）は、電気信号で接点を開閉して回路を切り替える部品である。","answer":true,"explanation":"コイルに通電すると接点が動作し、小さな信号で大きな回路を制御できます。"},
  {"id":282,"category":"設備保全の基礎","text":"シーケンス制御とは、あらかじめ決めた順序に従って動作を進める制御である。","answer":true,"explanation":"工程を順番に進める制御方式で、リレーやPLCで実現します。"},
  {"id":283,"category":"設備保全の基礎","text":"PLC（プログラマブル・コントローラ）は、プログラムで設備の動作を制御する装置である。","answer":true,"explanation":"入力（センサ）を受けて演算し、出力（アクチュエータ）を動かします。設備制御の中核です。"},
  {"id":284,"category":"設備保全の基礎","text":"近接センサは、対象物に接触せずにその有無を検出できる。","answer":true,"explanation":"磁気や静電容量の変化で検出します。接触しないため摩耗せず、寿命が長いのが利点です。"},
  {"id":285,"category":"設備保全の基礎","text":"光電センサは、光を利用して対象物の有無や位置を検出する。","answer":true,"explanation":"投光部と受光部の間の光の遮断・反射を利用します。汚れが付くと誤検出の原因になります。"},
  {"id":286,"category":"設備保全の基礎","text":"リミットスイッチは、機械的な接触によって位置や動作の終端を検出する。","answer":true,"explanation":"可動部が当たって接点が動作します。接触式のため摩耗や調整ずれに注意が必要です。"},
  {"id":287,"category":"設備保全の基礎","text":"インバータは、電動機の回転速度を変えるために周波数を制御する装置である。","answer":true,"explanation":"周波数を変えることで回転数を調整し、省エネや速度制御に役立ちます。"},
  {"id":288,"category":"設備保全の基礎","text":"オームの法則は、電圧＝電流×抵抗の関係を表す。","answer":true,"explanation":"E＝I×R。電気回路の最も基本的な関係式です。"},
  {"id":289,"category":"設備保全の基礎","text":"テスタ（回路計）は、電圧・電流・抵抗などを測定できる計測器である。","answer":true,"explanation":"導通確認や電圧測定など、電気系トラブルシューティングの基本工具です。"},
  {"id":290,"category":"設備保全の基礎","text":"絶縁抵抗計（メガー）は、電線や機器の絶縁の良否を調べるのに使う。","answer":true,"explanation":"絶縁抵抗が低いと漏電の危険があります。定期測定で劣化を早期に発見します。"},
  {"id":291,"category":"設備保全の基礎","text":"ノギスは、外側・内側の寸法や深さを測定できる測定器である。","answer":true,"explanation":"1台で外径・内径・深さ・段差が測れ、現場で広く使われます。"},
  {"id":292,"category":"設備保全の基礎","text":"マイクロメータは、ノギスより高い精度で寸法を測定できる。","answer":true,"explanation":"一般に1/1000mm単位まで読み取れ、精密な寸法測定に用います。"},
  {"id":293,"category":"設備保全の基礎","text":"ダイヤルゲージは、微小な変位や振れを測定するのに使われる。","answer":true,"explanation":"軸の振れや平面度、芯出しの確認などに使います。"},
  {"id":294,"category":"設備保全の基礎","text":"測定器は落としたり衝撃を与えても、外観に傷がなければ精度に影響しない。","answer":false,"explanation":"衝撃で内部機構が狂い、精度が失われることがあります。取扱いと定期校正が重要です。"},
  {"id":295,"category":"設備保全の基礎","text":"測定器の校正とは、正しい値を示すか基準と照合して確認・調整することである。","answer":true,"explanation":"定期的な校正により、測定値の信頼性を保ちます。"},
  {"id":296,"category":"設備保全の基礎","text":"第三角法は、日本の機械図面で一般的に用いられる投影法である。","answer":true,"explanation":"正面図を中心に、上に平面図、右に右側面図を配置します。"},
  {"id":297,"category":"設備保全の基礎","text":"図面の「かくれ線（不可視の線）」は、破線で表される。","answer":true,"explanation":"外形線は実線、見えない部分は破線、中心線は一点鎖線で表します。"},
  {"id":298,"category":"設備保全の基礎","text":"表面粗さの指示は、部品の仕上げ面の滑らかさを表す。","answer":true,"explanation":"摺動面やシール面など、機能上必要な面粗さを図面で指定します。"},
  {"id":299,"category":"設備保全の基礎","text":"はめあいとは、軸と穴の組み合わせにおける、すきまや締めしろの関係を表す。","answer":true,"explanation":"すきまばめ・しまりばめ・中間ばめがあり、用途に応じて公差で指定します。"},
  {"id":300,"category":"設備保全の基礎","text":"油圧作動油に空気が混入すると、動作が不安定になったり異音の原因になる。","answer":true,"explanation":"気泡の圧縮によりガクつき（キャビテーション・エアかみ）が生じ、機器を傷めます。"},
  {"id":301,"category":"生産の基本","text":"企業における安全管理では、法令に反する安全基準でも、独自に基準化してよいという理解でよい。","answer":false,"explanation":"社内の安全基準は法令を下回ってはならず、法令以上の水準で定めます。"},
  {"id":302,"category":"生産の基本","text":"安全衛生に関する活動では、事故防止に努め、万一災害が発生したときには、人体および企業活動に与える損害を最小限にとどめることが、ポイントと考えてよい。","answer":true,"explanation":"安全衛生活動は災害の未然防止と、発生時の被害最小化を目的にします。"},
  {"id":303,"category":"生産の基本","text":"安全衛生点検のうち、法令に基づく定期点検は、特定の検査技術や資格などを有する者が実行することが義務づけられているという理解でよい。","answer":true,"explanation":"法定点検には、必要な資格や検査能力を持つ者が実施するものがあります。"},
  {"id":304,"category":"生産の基本","text":"ヒューマンエラーを防止する方法の1つに、指差呼称があるという理解でよい。","answer":true,"explanation":"ヒューマンエラーは、人間の特性により起こり得る意図しない失敗や誤りです。"},
  {"id":305,"category":"生産の基本","text":"ハインリッヒの法則では、1件の重大災害の背後に29件の軽傷事故と300件の無傷事故があるとされる。","answer":true,"explanation":"ハインリッヒの法則は、1件の重大災害の背景に29件の軽傷事故と300件の無傷事故があるという考え方です。"},
  {"id":306,"category":"生産の基本","text":"作業服は、寒暖に応じて腕まくりをしたり、ボタンを外して着用して差し支えない。","answer":false,"explanation":"作業服は袖口やボタンを正しく閉じ、回転部への巻き込まれを防ぎます。"},
  {"id":307,"category":"生産の基本","text":"耳栓やイヤーマフは、作業時の騒音から聴覚を守るための保護具である。","answer":true,"explanation":"耳栓やイヤーマフは、騒音ばく露を低減して耳を保護します。"},
  {"id":308,"category":"生産の基本","text":"機械の電源を切った後も、惰力によって回転しているものを止める場合は、工具や棒を使用して停止させるという理解でよい。","answer":false,"explanation":"惰性で回転している機械には近づかず、完全に停止するまで待ちます。"},
  {"id":309,"category":"生産の基本","text":"クレーンで玉掛けをする場合は、吊り荷が回転したりズレたりすることがあるので、1本吊りは絶対にしてはならないという理解でよい。","answer":true,"explanation":"1本吊りは荷が回転・滑落しやすいため、原則として避けます。"},
  {"id":310,"category":"生産の基本","text":"空気中の酸素濃度が20％の場合、酸素欠乏状態にあると判断できる。","answer":false,"explanation":"酸素欠乏は空気中の酸素濃度が18％未満の状態です。"},
  {"id":311,"category":"生産の基本","text":"危険予知活動（KYK）は、作業で予測される危険要因を予知して、安全行動目標を決め、 人的要因の災害を防止する活動のことを指す。","answer":true,"explanation":"危険予知活動では、作業前に危険要因を洗い出し、安全行動目標を決めます。"},
  {"id":312,"category":"生産の基本","text":"リスクアセスメントは、潜在的な危険性または有害性を見つけ出し、これを除去、低減するための手法という位置づけである。","answer":true,"explanation":"リスクアセスメントは危険性・有害性を特定し、リスクを見積もって除去・低減する手法です。"},
  {"id":313,"category":"生産の基本","text":"「管理のサイクル（PDCAサイクル） を用いた管理」は、Plan（計画）→Do（実行）→Check（評価・診断）→Action（修正・改善）のサイクルを回すことを意味する。","answer":true,"explanation":"PDCAはPlan、Do、Check、Actionを繰り返す管理サイクルです。"},
  {"id":314,"category":"生産の基本","text":"品質管理では、経験やカンに頼るのではなく、事実に基づいて管理を進めることが重要と考えてよい。","answer":true,"explanation":"品質管理では、経験や勘だけでなく、客観的な事実やデータに基づいて判断します。"},
  {"id":315,"category":"生産の基本","text":"三現主義は、現場、現物、現象（現実）を重視する考え方を指す。","answer":true,"explanation":"三現主義は、現場・現物・現実を重視して事実を確認する考え方です。"},
  {"id":316,"category":"生産の基本","text":"同一の生産条件から生産された全製品を、すべて検査することに当たるものが「抜取り検査」である。","answer":false,"explanation":"抜取り検査はロットの一部を抽出して合否を判定します。全品を調べるのは全数検査です。"},
  {"id":317,"category":"生産の基本","text":"「メンバーシップ」は、集団を構成するメンバーとして、目標達成のため自己の能力・スキルを最大限活用して協力していくことを意味する。","answer":true,"explanation":"メンバーシップは、各自が能力を発揮し役割を果たして集団目標に貢献することです。"},
  {"id":318,"category":"生産の基本","text":"Off-JTは、主に職場の業務を離れて進める教育訓練と考えてよい。","answer":true,"explanation":"Off-JTは、通常の職場業務から離れて行う集合研修などの教育訓練です。"},
  {"id":319,"category":"生産の基本","text":"自己啓発は、上司や先輩が個別に部下を教育・指導する方法を指す。","answer":false,"explanation":"自己啓発は、本人が自らの意思で知識や技能を学ぶ活動です。"},
  {"id":320,"category":"生産の基本","text":"本や映像など用いて、人以外から学ぶ教育方法に当たるものが「伝達教育」である。","answer":false,"explanation":"伝達教育は、学んだ人がその内容を職場のほかのメンバーへ伝える教育方法です。"},
  {"id":321,"category":"生産の基本","text":"典型7公害の1つに、土壌汚染があるとされる。","answer":true,"explanation":"典型7公害には、大気汚染、水質汚濁、土壌汚染、騒音、振動、地盤沈下、悪臭があります。"},
  {"id":322,"category":"生産の基本","text":"廃棄物を原材料として再生利用するという考え方を「リサイクル」という。","answer":true,"explanation":"リサイクルは、廃棄物を原材料などとして再生利用することです。"},
  {"id":323,"category":"生産の基本","text":"エコマークは、有害化学物質を含有する製品につけられる目印に該当する。","answer":false,"explanation":"エコマークは、環境保全に役立つ商品を消費者が選ぶための目印です。"},
  {"id":324,"category":"効率化とロス","text":"生産保全（PM）の手段の1つに、事後保全（BM）があるという理解でよい。","answer":true,"explanation":"生産保全は、設備のライフサイクル全体で生産性を最も経済的に高める保全活動です。"},
  {"id":325,"category":"効率化とロス","text":"状態基準保全（CBM）は、一定の周期で行われる保全のこととされる。","answer":false,"explanation":"CBMは設備状態を監視し、劣化の兆候に応じて保全する方式です。一定周期で行う方式はTBMです。"},
  {"id":326,"category":"効率化とロス","text":"設備を使用開始前の正しい状態に戻すことを「改良保全（CM）」という。","answer":false,"explanation":"改良保全は、故障しにくく保全しやすい設備へ改善する活動です。"},
  {"id":327,"category":"効率化とロス","text":"保全予防（MP）は、保全作業における災害ゼロを目指す活動に該当する。","answer":false,"explanation":"保全予防は、新設備の計画・設計段階から故障しにくく保全しやすい設備づくりを行う考え方です。"},
  {"id":328,"category":"効率化とロス","text":"人の効率化を阻害するロスは、標準工数に対して、実際にどれだけの工数を必要としたかという比率で考えるという理解でよい。","answer":true,"explanation":"人の効率は、標準工数に対して実際に要した工数の関係などで評価します。"},
  {"id":329,"category":"効率化とロス","text":"原単位の効率化を阻害する3大ロスは、管理ロス、動作ロス、編成ロスとされる。","answer":false,"explanation":"原単位の3大ロスは、歩留まりロス・エネルギーロス・型・治工具ロスです。管理・動作・編成ロスは人の効率に関係します。"},
  {"id":330,"category":"効率化とロス","text":"速度稼働率は、「実際サイクルタイム÷基準サイクルタイム×100」で算出する。","answer":false,"explanation":"速度稼働率は「基準サイクルタイム÷実際サイクルタイム×100」で求めるため、分子と分母が逆です。"},
  {"id":331,"category":"効率化とロス","text":"潜在欠陥には、物理的潜在欠陥と心理的潜在欠陥の2つのタイプがあるとされる。","answer":true,"explanation":"潜在欠陥は、物理的潜在欠陥と心理的潜在欠陥に分けて考えます。"},
  {"id":332,"category":"効率化とロス","text":"自然劣化は、設備に対し清掃や給油などやるべきことをやっていないために起こるという理解でよい。","answer":false,"explanation":"自然劣化は、正しく使用していても時間経過や摩耗で進む劣化です。清掃・給油不足で進むのは強制劣化です。"},
  {"id":333,"category":"効率化とロス","text":"故障ゼロへの5つの対策の1つに「設計上の弱点を改善する」があるとされる。","answer":true,"explanation":"故障ゼロには、基本条件の整備、使用条件の遵守、劣化復元、弱点改善、運転・保全技能向上が重要です。"},
  {"id":334,"category":"効率化とロス","text":"機能停止型故障は、システムや設備の部分的な機能低下によって、歩留まりや速度の低下を発生させる故障と考えてよい。","answer":false,"explanation":"機能停止型故障は設備の機能が完全に失われる故障です。性能低下や歩留まり低下は機能低下型故障です。"},
  {"id":335,"category":"効率化とロス","text":"故障のメカニズムは、故障の原因が故障として表面に現れるまでの過程のことを指す。","answer":true,"explanation":"故障のメカニズムは、原因がどのような過程を経て故障として現れるかを示します。"},
  {"id":336,"category":"効率化とロス","text":"設備の摩耗・老化現象などによって、時間の経過とともに故障率が大きくなる時期のことに当たるものが「初期故障期」である。","answer":false,"explanation":"初期故障期は、設計・製作・据付などに起因する故障が初期に多く発生し、その後減少する時期です。"},
  {"id":337,"category":"効率化とロス","text":"故障度数率は、負荷時間あたりの故障停止時間の割合とされる。","answer":false,"explanation":"故障度数率は、負荷時間に対する故障停止回数の割合です。"},
  {"id":338,"category":"効率化とロス","text":"規定の期間中、故障が発生しなかった設備は、故障が発生した設備よりも信頼性が高いと判断できる。","answer":true,"explanation":"信頼性は、所定の条件と期間で要求機能を故障なく果たす性質です。"},
  {"id":339,"category":"効率化とロス","text":"ライフサイクルコスト（LCC）は、設備が故障してから再稼働するまでにかかる総費用のことを指す。","answer":false,"explanation":"LCCは、取得・運用・保全・廃棄まで、設備の生涯にかかる総費用です。"},
  {"id":340,"category":"効率化とロス","text":"MTBFは、故障の修復にかかった時間の平均値という位置づけである。","answer":false,"explanation":"MTBFは、修理可能な設備における故障から次の故障までの平均稼働時間です。"},
  {"id":341,"category":"効率化とロス","text":"MTTFは、修理可能な設備の故障から次の故障までの動作時間の平均値とされる。","answer":false,"explanation":"MTTFは、修理しない機器が故障するまでの平均時間です。"},
  {"id":342,"category":"効率化とロス","text":"自主保全として進める保全活動は、劣化を防ぐ活動、劣化を測る活動、劣化を復元する活動の3つに分類されるという理解でよい。","answer":true,"explanation":"自主保全の保全活動は、劣化を防ぐ・測る・復元する活動に整理できます。"},
  {"id":343,"category":"設備の日常保全","text":"自主保全活動のステップ方式では、ステップの活動を順番に沿って進めなければならないという理解でよい。","answer":true,"explanation":"自主保全は各ステップを順に進め、診断に合格してから次のステップへ進みます。"},
  {"id":344,"category":"設備の日常保全","text":"自主保全活動におけるステップ診断では、サークルメンバー全員が役割分担して発表・発言するものとされる。","answer":true,"explanation":"正しい記述です。用語の定義と適用範囲をあわせて覚えておきましょう。"},
  {"id":345,"category":"設備の日常保全","text":"自主保全で実施するすべての作業は、仕事そのものであるという認識を徹底する必要があるとされる。","answer":true,"explanation":"自主保全活動は本来業務の一部であり、仕事と切り離した付加作業ではありません。"},
  {"id":346,"category":"設備の日常保全","text":"活動板は、活動方針や管理指標などが、ひと目で誰にでもわかるサークル活動のツールと考えてよい。","answer":true,"explanation":"活動板は方針・目標・計画・進捗・成果を誰でも一目で確認できるようにするツールです。"},
  {"id":347,"category":"設備の日常保全","text":"ワンポイントレッスンは、日常活動の中で学習するために有効な伝達のツールに該当する。","answer":true,"explanation":"ワンポイントレッスンは、短時間で一つの知識や改善事例を共有する教育ツールです。"},
  {"id":348,"category":"設備の日常保全","text":"ミーティングは、1回あたりの時間を長くとり、回数は少なくするとよいという理解でよい。","answer":false,"explanation":"小集団ミーティングは、短時間・高頻度で行い、全員参加を促すことが基本です。"},
  {"id":349,"category":"設備の日常保全","text":"エフは、設備の不具合箇所だけでなく、保全性や安全性の悪い場所にも取り付けるという理解でよい。","answer":true,"explanation":"エフは、不具合・安全・保全性などの問題箇所を見える化し、処置状況を管理する札です。"},
  {"id":350,"category":"設備の日常保全","text":"定点撮影は、対象物の改善・改良の変化を、定期的にとらえるために利用されるという理解でよい。","answer":true,"explanation":"定点撮影は同じ位置・角度から継続撮影し、改善前後の変化を比較する方法です。"},
  {"id":351,"category":"設備の日常保全","text":"マップによる管理では、不具合箇所などをレイアウト上で表現し、何をやるべきか、何をやったかを明確にすると考えられる。","answer":true,"explanation":"マップ管理は、不具合箇所や対策状況を設備・職場レイアウト上に表示する方法です。"},
  {"id":352,"category":"設備の日常保全","text":"五感点検では、微欠陥を発見することはできないという理解でよい。","answer":false,"explanation":"五感点検では、見る・聞く・触る・嗅ぐなどを活用して微欠陥や異常兆候を発見します。"},
  {"id":353,"category":"設備の日常保全","text":"正しい状態から外れているものに対しては、改善活動を実施する前に、まず復元を実施するとされる。","answer":true,"explanation":"まず正しい状態へ復元し、その後に再発防止や機能向上の改善を行います。"},
  {"id":354,"category":"設備の日常保全","text":"自主保全第１ステップ（初期清掃）における基本条件の整備では、清掃のみ行い、給油・ 増し締めは行わないという理解でよい。","answer":false,"explanation":"初期清掃では、清掃を通じた点検に加え、給油・増し締めなどの基本条件も整えます。"},
  {"id":355,"category":"設備の日常保全","text":"設備の清掃を実行することで、機能の維持や誤動作の防止といった効果も期待できるという理解でよい。","answer":true,"explanation":"正しい記述です。用語の定義と適用範囲をあわせて覚えておきましょう。"},
  {"id":356,"category":"設備の日常保全","text":"発生源そのものを完全に絶つことに当たるものが「自主保全第2ステップ（発生源・困難箇所対策）における局所化」である。","answer":false,"explanation":"局所化は、汚れや漏れを発生源の近くに封じ込め、飛散範囲を小さくする対策です。"},
  {"id":357,"category":"設備の日常保全","text":"「自主保全第2ステップ（発生源・困難箇所対策）における困難箇所」は、作業改善することができない箇所を意味する。","answer":false,"explanation":"困難箇所は、清掃・点検・給油などがしにくい場所であり、改善して作業しやすくします。"},
  {"id":358,"category":"設備の日常保全","text":"自主保全第3ステップ（自主保全仮基準の作成）において、サークル内で自ら基準書をつくることによって、役割意識が高まり、責任感が養われるという理解でよい。","answer":true,"explanation":"第3ステップでは、清掃・給油・点検を短時間で確実に行う自主保全仮基準を自ら作成します。"},
  {"id":359,"category":"設備の日常保全","text":"給油方法を見直す際は、油種を明確にして、できれば油種を統一すると考えられる。","answer":true,"explanation":"給油では油種・量・周期・箇所を明確にし、誤給油を防ぐため可能な範囲で油種を統一します。"},
  {"id":360,"category":"設備の日常保全","text":"自主保全第4ステップ（総点検）の目的の1つに、設備の構造・機能・原理とあるべき姿を理解することが含まれるという理解でよい。","answer":true,"explanation":"総点検では、設備の構造・機能・原理を学び、五感点検と目で見る管理を身につけます。"},
  {"id":361,"category":"設備の日常保全","text":"自主保全第4ステップ（総点検）において、総点検教育訓練スケジュールはサークルメンバーが、日常点検仮基準は保全スタッフや現場管理者が作成するとされる。","answer":false,"explanation":"総点検では、設備の構造・機能・原理を学び、五感点検と目で見る管理を身につけます。"},
  {"id":362,"category":"改善・解析","text":"ロス合計が200件で、そのうちB工程が60件なら、B工程の構成比は60％である。","answer":false,"explanation":"60÷200×100＝30％であり、60％ではありません。"},
  {"id":363,"category":"改善・解析","text":"総点検教育後の技能評価で「締結」が5点、ほかの項目が4点以下なら、最高評価の項目は締結である。","answer":true,"explanation":"評価値が最も大きい項目が最高評価となるため、この条件では締結が該当します。"},
  {"id":364,"category":"改善・解析","text":"度数分布表は、ある品質特性に対するバラツキの状況や、規格との関連を調査するために使われるという理解でよい。","answer":true,"explanation":"度数分布表はデータを階級ごとに集計し、ヒストグラム作成やばらつき把握に使います。"},
  {"id":365,"category":"改善・解析","text":"管理図の例として、p 管理図や np 管理図が含まれるという理解でよい。","answer":true,"explanation":"管理図は、中心線と管理限界線を用いて工程が統計的に安定しているかを監視します。"},
  {"id":366,"category":"改善・解析","text":"正規分布の分布曲線は、ベル型をしたもので、中心線の左右は対称と考えてよい。","answer":true,"explanation":"正規分布は中央が高い左右対称のベル形の分布です。"},
  {"id":367,"category":"改善・解析","text":"標準偏差は、データのバラツキを数量的に表すものに該当する。","answer":true,"explanation":"標準偏差は、データのばらつきの大きさを数値で表す指標です。"},
  {"id":368,"category":"改善・解析","text":"工程能力は、定められた規格限度内で、製品を生産できる能力という位置づけである。","answer":true,"explanation":"工程能力は、安定した工程が規格内の製品をつくる能力です。"},
  {"id":369,"category":"改善・解析","text":"なぜなぜ分析は、複数の危険源をスタートとして、それらが引き起こすすべての不具合を明確にする手法とされる。","answer":false,"explanation":"なぜなぜ分析は、現象に対して「なぜ」を繰り返し、根本原因を追究する手法です。"},
  {"id":370,"category":"改善・解析","text":"PM分析では、現象を物理的に解析し、メカニズムを理解して生産活動の4要素（4M） との関連性を追求していくという理解でよい。","answer":true,"explanation":"PM分析は、現象を物理的に解析し、4Mとの関連から慢性ロスの要因を追究します。"},
  {"id":371,"category":"改善・解析","text":"慢性的に発生するロスは、突発的に発生するロスよりも、原因がつかみやすいことが多いという理解でよい。","answer":false,"explanation":"慢性ロスは原因が複雑に絡み合い、突発ロスより真因をつかみにくい傾向があります。"},
  {"id":372,"category":"改善・解析","text":"5W2Hを使った質問法において、2つの Hは、Hear（聞く）と Help（助ける）を示しているという理解でよい。","answer":false,"explanation":"5W2HはWho、What、When、Where、Why、How、How muchです。"},
  {"id":373,"category":"改善・解析","text":"タクトタイムは、「1日の計画生産数×良品率」を「1日の稼働時間」で割って求める。","answer":false,"explanation":"タクトタイムは、一般に「稼働可能時間÷必要生産数」で求めます。分子と分母が逆です。"},
  {"id":374,"category":"改善・解析","text":"内段取りは、機械設備を止めなくてもできる段取りのことと考えてよい。","answer":false,"explanation":"内段取りは設備を停止しなければできない段取り作業です。停止せず行えるものは外段取りです。"},
  {"id":375,"category":"改善・解析","text":"VEにおける価値は、機能をコストで割った関係で表すことができる。","answer":true,"explanation":"VEでは、価値＝機能÷コストで表します。"},
  {"id":376,"category":"改善・解析","text":"故障モードが及ぼす影響度を解析して、故障の未然防止を図る手法に当たるものが「FMEA」である。","answer":true,"explanation":"FMEAは、想定される故障モードと影響を事前に評価し、未然防止につなげる手法です。"},
  {"id":377,"category":"設備保全の基礎","text":"「おねじ」は、円筒内にみぞを切ったねじのことを意味する。","answer":false,"explanation":"おねじは円筒の外側にねじ山を設けたものです。内側に設けるのはめねじです。"},
  {"id":378,"category":"設備保全の基礎","text":"ボルトのゆるみ止め方法の1つに、二重ナット（ダブルナット）があるという理解でよい。","answer":true,"explanation":"二重ナットは2個のナットを互いに締め付け、緩みを防止する方法です。"},
  {"id":379,"category":"設備保全の基礎","text":"ボルトの合マークは、ボルトまたはナットの表面だけに線を引けばよい。","answer":false,"explanation":"合マークは締結部と固定側にまたがって記入し、線のずれで緩みを確認します。"},
  {"id":380,"category":"設備保全の基礎","text":"軸受には、ころがり軸受とすべり軸受があるという理解でよい。","answer":true,"explanation":"すべり軸受は油膜で軸を支持し、高速・高荷重や大型機器にも使用されます。"},
  {"id":381,"category":"設備保全の基礎","text":"歯車は、回転軸の振動や騒音を小さくするために使用されるという理解でよい。","answer":false,"explanation":"歯車は歯のかみ合いで回転と動力を正確に伝達します。軸間距離が長い場合はチェーンやベルトが適します。"},
  {"id":382,"category":"設備保全の基礎","text":"Vベルトは、ベルトとプーリーの摩擦力によって動力を伝達するという理解でよい。","answer":true,"explanation":"Vベルトはベルトとプーリー間の摩擦力で動力を伝達します。"},
  {"id":383,"category":"設備保全の基礎","text":"密封装置（密封部品）は、機械や装置の内部からの液体漏れや、外部からの異物の侵入を防止するために活用されるという理解でよい。","answer":true,"explanation":"密封装置にはガスケット、パッキン、オイルシール、メカニカルシールなどがあります。"},
  {"id":384,"category":"設備保全の基礎","text":"潤滑油の温度が上昇すると、酸化速度は遅くなるという理解でよい。","answer":false,"explanation":"潤滑油は温度が高いほど酸化が進みやすく、劣化速度が増します。"},
  {"id":385,"category":"設備保全の基礎","text":"エアシリンダーは、機械エネルギーを圧縮空気エネルギーに変える機器とされる。","answer":false,"explanation":"エアシリンダーは圧縮空気のエネルギーを直線運動の機械エネルギーへ変換します。"},
  {"id":386,"category":"設備保全の基礎","text":"粘度指数が高い油は、温度変化による粘度変化が大きいという理解でよい。","answer":false,"explanation":"粘度指数が高い油ほど、温度変化による粘度変化が小さい油です。"},
  {"id":387,"category":"設備保全の基礎","text":"オームの法則では、電流は「抵抗÷電圧」で求める。","answer":false,"explanation":"電流は「電圧÷抵抗」で求めます。"},
  {"id":388,"category":"設備保全の基礎","text":"接地は、電気機器や配線類などの絶縁不良や損傷により、電流が他に漏れて流れている現象という位置づけである。","answer":false,"explanation":"接地は電気機器の金属部などを大地へ接続する安全措置です。絶縁不良で電流が漏れる現象は漏電です。"},
  {"id":389,"category":"設備保全の基礎","text":"インバーターは、低圧回路の電路保護に使用される遮断器とされる。","answer":false,"explanation":"インバーターは周波数や電圧を制御し、主にモーターの回転速度を調整します。"},
  {"id":390,"category":"設備保全の基礎","text":"レギュレーターは、圧縮空気の圧力を使用目的に応じて制御するために利用されるという理解でよい。","answer":true,"explanation":"レギュレーターは、使用側の圧縮空気圧力を設定値に調整します。"},
  {"id":391,"category":"設備保全の基礎","text":"ルブリケーターは、電磁弁やシリンダーの摺動部などに潤滑油を供給するために活用されるという理解でよい。","answer":true,"explanation":"ルブリケーターは圧縮空気中に油霧を供給し、下流機器を潤滑します。"},
  {"id":392,"category":"設備保全の基礎","text":"油圧バルブのうち、圧力制御弁は、アクチュエーターの仕事の大きさを決める弁という位置づけである。","answer":true,"explanation":"圧力制御弁は圧力を調整し、アクチュエーターが発生する力・トルクを制御します。"},
  {"id":393,"category":"設備保全の基礎","text":"リミットスイッチは、主に圧力の変化を検出するセンサーとされる。","answer":false,"explanation":"リミットスイッチは機械的な接触で位置や動作端を検出するスイッチです。"},
  {"id":394,"category":"設備保全の基礎","text":"純鉄は、ステンレス鋼よりも腐食に強い金属材料と考えてよい。","answer":false,"explanation":"ステンレス鋼はクロムなどを含み、一般に純鉄より耐食性に優れます。"},
  {"id":395,"category":"設備保全の基礎","text":"非鉄金属材料の例として、アルミニウムが挙げられるという理解でよい。","answer":true,"explanation":"アルミニウムは鉄を主成分としない代表的な非鉄金属です。"},
  {"id":396,"category":"設備保全の基礎","text":"金属部品の結合方法の1つに、リベットで結合する方法があるという理解でよい。","answer":true,"explanation":"リベット接合は、リベットをかしめて金属部品などを永久結合する方法です。"},
  {"id":397,"category":"設備保全の基礎","text":"工業材料の塗装は、防食や防湿、装飾などを目的として行われるという理解でよい。","answer":true,"explanation":"塗装は防食・防湿・美観・識別などを目的として行います。"},
  {"id":398,"category":"設備保全の基礎","text":"ゴムは、ベルトやパッキンなどの材料として利用されるという理解でよい。","answer":true,"explanation":"ゴムは弾性と密封性を生かし、ベルト、ホース、パッキンなどに使用されます。"},
  {"id":399,"category":"設備保全の基礎","text":"ハンドタップは、めねじを切る切削工具に該当する。","answer":true,"explanation":"ハンドタップは、下穴にめねじを加工する切削工具です。"},
  {"id":400,"category":"設備保全の基礎","text":"寸法公差（サイズ公差）は、最大許容寸法と最小許容寸法の差という位置づけである。","answer":true,"explanation":"寸法公差は、最大許容寸法と最小許容寸法の差です。図面寸法と実測値の差ではありません。"},
  {"id":401,"category":"生産の基本","text":"基礎事項として、安全衛生に関する活動では、事故防止に努め、万一災害が発生したときには、人体および企業活動に与える損害を最小限にとどめることが、ポイントと考えてよい。","answer":true,"explanation":"安全衛生活動は災害の未然防止と、発生時の被害最小化を目的にします。"},
  {"id":402,"category":"生産の基本","text":"基礎事項として、安全衛生点検のうち、法令に基づく定期点検は、特定の検査技術や資格などを有する者が実行することが義務づけられているという理解でよい。","answer":true,"explanation":"法定点検には、必要な資格や検査能力を持つ者が実施するものがあります。"},
  {"id":403,"category":"生産の基本","text":"機械や設備に異常が発生しても、安全側に作動するように配慮された設備の考え方に当たるものが「フェイルセーフ」である。","answer":true,"explanation":"フェイルセーフは、機器が故障した場合でも危険側ではなく安全側へ作動させる設計思想です。"},
  {"id":404,"category":"生産の基本","text":"ハインリッヒの法則によると、1件の休業災害を起こす裏には、100件の不休災害があるとされているという理解でよい。","answer":false,"explanation":"ハインリッヒの法則では、1件の重大災害の背後に29件の軽傷事故と300件の無傷事故があるとされます。"},
  {"id":405,"category":"生産の基本","text":"機械を止めるときに、惰力で回転しているものは、工具や棒を使用して停止するという理解でよい。","answer":false,"explanation":"惰性で回転している機械には近づかず、完全に停止するまで待ちます。"},
  {"id":406,"category":"生産の基本","text":"酸素濃度が18％未満の場合、酸素欠乏状態にあると判断できるという理解でよい。","answer":true,"explanation":"酸素欠乏は空気中の酸素濃度が18％未満の状態です。"},
  {"id":407,"category":"生産の基本","text":"リスクアセスメントは、人が行っていた作業を機械化・自動化することで、作業の効率化を図る手法という位置づけである。","answer":false,"explanation":"リスクアセスメントは危険性・有害性を特定し、リスクを見積もって除去・低減する手法です。"},
  {"id":408,"category":"生産の基本","text":"労働安全衛生マネジメントシステム（OSHMS）は、生産活動の結果、排出される廃棄物をゼロにして、循環型産業システムを目指すものとされる。","answer":false,"explanation":"OSHMSは、組織的・継続的に労働安全衛生水準を高めるマネジメントの仕組みです。"},
  {"id":409,"category":"生産の基本","text":"Plan（計画）→Do（実行）→Check（評価・ 診断）→Action（修正・改善）のサイクルを回すことを「管理のサイクル（PDCAサイクル）」という。","answer":true,"explanation":"PDCAはPlan、Do、Check、Actionを繰り返す管理サイクルです。"},
  {"id":410,"category":"生産の基本","text":"三現主義は、実現、表現、再現を重視する考え方に該当する。","answer":false,"explanation":"三現主義は、現場・現物・現実を重視して事実を確認する考え方です。"},
  {"id":411,"category":"生産の基本","text":"品質管理では、事実に基づく管理よりも、カンを重視して管理を実施することが重要という位置づけである。","answer":false,"explanation":"品質管理では、経験や勘だけでなく、客観的な事実やデータに基づいて判断します。"},
  {"id":412,"category":"生産の基本","text":"「抜取り検査」は、同一の生産条件から生産された製品を、すべて検査することを意味する。","answer":false,"explanation":"抜取り検査はロットの一部を抽出して合否を判定します。全品を調べるのは全数検査です。"},
  {"id":413,"category":"生産の基本","text":"作業標準には、具体的な注意事項などは記入せず、作業条件、使用道具、作業手順のみを簡潔に記載するという理解でよい。","answer":false,"explanation":"作業標準には、条件・道具・手順に加えて、品質や安全上の急所・注意点も明記します。"},
  {"id":414,"category":"生産の基本","text":"メンバーシップは、リーダーの指示により、目標達成のため自己の能力・スキルを最大限活用して協力していくことを指す。","answer":true,"explanation":"メンバーシップは、各自が能力を発揮し役割を果たして集団目標に貢献することです。"},
  {"id":415,"category":"生産の基本","text":"Off-JTは、主に職場の業務を離れて実施する教育という位置づけである。","answer":true,"explanation":"Off-JTは、通常の職場業務から離れて行う集合研修などの教育訓練です。"},
  {"id":416,"category":"生産の基本","text":"「自己啓発」は、自分自身で勉強し理解を深める手法を意味する。","answer":true,"explanation":"自己啓発は、本人が自らの意思で知識や技能を学ぶ活動です。"},
  {"id":417,"category":"生産の基本","text":"伝達教育の例として、通信教育やオンラインセミナーを用いて、自主的に学習することが挙げられるという理解でよい。","answer":false,"explanation":"伝達教育は、学んだ人がその内容を職場のほかのメンバーへ伝える教育方法です。"},
  {"id":418,"category":"生産の基本","text":"就業規則は、各社が労働基準法に基づいて、勤務の条件などを定めた規則を指す。","answer":true,"explanation":"就業規則は、労働条件や服務規律などを定める職場の基本的な規則です。"},
  {"id":419,"category":"生産の基本","text":"年次有給休暇は、労働基準法で、利用目的が制限されている休暇という位置づけである。","answer":false,"explanation":"年次有給休暇は、原則として利用目的を労働者が自由に決められます。"},
  {"id":420,"category":"生産の基本","text":"典型7公害の1つに、騒音があるとされる。","answer":true,"explanation":"騒音は典型7公害の一つです。"},
  {"id":421,"category":"生産の基本","text":"Research（リサーチ）、Reform（リフォーム）、Recover（リカバー）の3つの Rの総称を「環境管理における3R」という。","answer":false,"explanation":"環境管理の3RはReduce、Reuse、Recycleです。"},
  {"id":422,"category":"生産の基本","text":"基礎事項として、エコマークは、有害化学物質を含有する製品につけられる目印に該当する。","answer":false,"explanation":"エコマークは、環境保全に役立つ商品を消費者が選ぶための目印です。"},
  {"id":423,"category":"生産の基本","text":"清掃によって工場内のゴミをゼロにする活動に当たるものが「ゼロ・エミッション」である。","answer":false,"explanation":"ゼロ・エミッションは、廃棄物を資源として活用し、最終廃棄を限りなくゼロに近づける考え方です。"},
  {"id":424,"category":"効率化とロス","text":"生産保全は、生産性を高めるためのもっとも経済的な保全活動のこととされる。","answer":true,"explanation":"生産保全は、設備のライフサイクル全体で生産性を最も経済的に高める保全活動です。"},
  {"id":425,"category":"効率化とロス","text":"保全手段の分類では、予防保全と並んで事後保全も維持活動に含まれる。","answer":true,"explanation":"設備を正常に維持する手段には、予防保全と事後保全があります。"},
  {"id":426,"category":"効率化とロス","text":"予知保全は、時間基準保全（TBM）とも呼ばれるという理解でよい。","answer":false,"explanation":"予知保全は設備の状態・傾向を監視し、故障時期を予測して行う保全です。"},
  {"id":427,"category":"効率化とロス","text":"改良保全（CM）と保全予防（MP）は、人を対象として作業方法の見直しを実施する改善活動という位置づけである。","answer":false,"explanation":"改良保全は、故障しにくく保全しやすい設備へ改善する活動です。"},
  {"id":428,"category":"効率化とロス","text":"TPMは、「私つくる人、あなた直す人」を徹底するための活動とされる。","answer":false,"explanation":"TPMは全部門・全員参加で設備効率の最大化とロスゼロを目指す活動です。"},
  {"id":429,"category":"効率化とロス","text":"TPMの基本理念の1つは、予防哲学（未然防止）と考えてよい。","answer":true,"explanation":"TPMの基本理念には、予防哲学、ゼロ指向、全員参加があります。"},
  {"id":430,"category":"効率化とロス","text":"TPM活動の8本柱の1つは、品質保全に該当する。","answer":true,"explanation":"TPMは全部門・全員参加で設備効率の最大化とロスゼロを目指す活動です。"},
  {"id":431,"category":"効率化とロス","text":"人の効率化を阻害するロスは、標準工数に対してどれだけの工数を必要としたかという比率でとらえるという理解でよい。","answer":true,"explanation":"人の効率は、標準工数に対して実際に要した工数の関係などで評価します。"},
  {"id":432,"category":"効率化とロス","text":"基礎事項として、原単位の効率化を阻害する3大ロスは、管理ロス、動作ロス、編成ロスとされる。","answer":false,"explanation":"原単位の3大ロスは、歩留まりロス・エネルギーロス・型・治工具ロスです。管理・動作・編成ロスは人の効率に関係します。"},
  {"id":433,"category":"効率化とロス","text":"正味稼働率は、設備が本来持っている能力と、実際のスピードの比率と考えてよい。","answer":false,"explanation":"正味稼働率は、実際の加工時間に対する正味の稼働時間を示し、チョコ停や空転の影響を受けます。"},
  {"id":434,"category":"効率化とロス","text":"故障のメカニズムを解析するためには、設備の機能や構造をよく理解する必要となるという理解でよい。","answer":true,"explanation":"故障のメカニズムは、原因がどのような過程を経て故障として現れるかを示します。"},
  {"id":435,"category":"効率化とロス","text":"変形や折損などの故障状態の分類のことに当たるものが「故障モード」である。","answer":true,"explanation":"故障モードは、折損・摩耗・変形・漏れなど、故障が現れた状態の分類です。"},
  {"id":436,"category":"効率化とロス","text":"電気配線は、外見からは異常がわからないため、点検する必要はないという理解でよい。","answer":false,"explanation":"誤りです。記述中の対象・条件・定義のいずれかが正しくありません。"},
  {"id":437,"category":"効率化とロス","text":"寿命特性曲線（バスタブ曲線）において、設備の故障期は、自然故障期、突発故障期、老化故障期の3つに分類されるという理解でよい。","answer":false,"explanation":"バスタブ曲線は、初期故障期・偶発故障期・摩耗故障期の3期間で表します。"},
  {"id":438,"category":"効率化とロス","text":"基礎事項として、ライフサイクルコスト（LCC）は、設備が故障してから再稼働するまでにかかる総費用のことを指す。","answer":false,"explanation":"LCCは、取得・運用・保全・廃棄まで、設備の生涯にかかる総費用です。"},
  {"id":439,"category":"効率化とロス","text":"計画した期間中に故障せずに稼働した設備は、信頼性の高い設備と判断できる。","answer":true,"explanation":"信頼性は、所定の条件と期間で要求機能を故障なく果たす性質です。"},
  {"id":440,"category":"効率化とロス","text":"MTBFは、「故障停止時間の合計÷故障停止回数」で算出する。","answer":false,"explanation":"MTBFは稼働時間の合計を故障回数で割った平均故障間隔です。故障停止時間を用いるのはMTTRの考え方です。"},
  {"id":441,"category":"効率化とロス","text":"MTTFは、修理可能な設備の故障から次の故障までの動作時間の平均値と考えてよい。","answer":false,"explanation":"MTTFは、修理しない機器が故障するまでの平均時間です。"},
  {"id":442,"category":"効率化とロス","text":"故障強度率は、「負荷時間の合計÷故障停止時間の合計×100」で求める。","answer":false,"explanation":"故障強度率は「故障停止時間÷負荷時間×100」で求めるため、分子と分母が逆です。"},
  {"id":443,"category":"設備の日常保全","text":"「自分の設備は自分で守る」ことを目的として、設備の日常点検・異常の早期発見・精度チェックなどを行うことに当たるものが「自主保全」である。","answer":true,"explanation":"自主保全は、オペレーターが日常点検や基本条件整備を担い、自分の設備を守る活動です。"},
  {"id":444,"category":"設備の日常保全","text":"自主保全において、オペレーターに求められる4つの能力の1つは、処置・回復能力とされる。","answer":true,"explanation":"オペレーターには、異常発見、処置・回復、条件設定、維持管理などの能力が求められます。"},
  {"id":445,"category":"設備の日常保全","text":"基礎事項として、自主保全として進める保全活動は、劣化を防ぐ活動、劣化を測る活動、劣化を復元する活動の3つに分類されるという理解でよい。","answer":true,"explanation":"自主保全の保全活動は、劣化を防ぐ・測る・復元する活動に整理できます。"},
  {"id":446,"category":"設備の日常保全","text":"自主保全では、オペレーターが行っていた保全業務を、すべて保全部門に任せることを目的とすると考えられる。","answer":false,"explanation":"誤りです。記述中の対象・条件・定義のいずれかが正しくありません。"},
  {"id":447,"category":"設備の日常保全","text":"自主保全のステップ方式では、1つのステップが完了した段階で管理者やスタッフによる診断を受け、合格すると次のステップに進むことができるという理解でよい。","answer":true,"explanation":"自主保全は各ステップを順に進め、診断に合格してから次のステップへ進みます。"},
  {"id":448,"category":"設備の日常保全","text":"自主保全で実施するすべての作業は、仕事とは別の作業であるという認識を徹底するとされる。","answer":false,"explanation":"自主保全活動は本来業務の一部であり、仕事と切り離した付加作業ではありません。"},
  {"id":449,"category":"設備の日常保全","text":"重複小集団組織は、1つのグループにつき10人以上のメンバーで構成しなければならないという理解でよい。","answer":false,"explanation":"重複小集団は、階層ごとの小集団を重ねて方針と活動をつなぐ組織で、人数を10人以上に固定するものではありません。"},
  {"id":450,"category":"設備の日常保全","text":"定点撮影は、対象物の改善・改良の変化を、定期的・段階的にとらえるために利用する管理方式に該当する。","answer":true,"explanation":"定点撮影は同じ位置・角度から継続撮影し、改善前後の変化を比較する方法です。"},
  {"id":451,"category":"設備の日常保全","text":"正しい状態から外れているものに対しては、復元する前に、改善を実施するものとされる。","answer":false,"explanation":"まず正しい状態へ復元し、その後に再発防止や機能向上の改善を行います。"},
  {"id":452,"category":"設備の日常保全","text":"基礎事項として、五感点検では、微欠陥を発見することはできないという理解でよい。","answer":false,"explanation":"五感点検では、見る・聞く・触る・嗅ぐなどを活用して微欠陥や異常兆候を発見します。"},
  {"id":453,"category":"設備の日常保全","text":"エフ付けした後、その場で処置できる不具合については、その場で処置してエフ取りをするという理解でよい。","answer":true,"explanation":"エフは、不具合・安全・保全性などの問題箇所を見える化し、処置状況を管理する札です。"},
  {"id":454,"category":"設備の日常保全","text":"配管・継手類からのにじみ・漏れのチェックは、設備の運転中でも実施可能な自主保全活動に該当する。","answer":true,"explanation":"正しい記述です。用語の定義と適用範囲をあわせて覚えておきましょう。"},
  {"id":455,"category":"設備の日常保全","text":"自主保全第3ステップ（自主保全仮基準の作成）の目的の1つに、短時間で確実に基本条件の整備ができる行動基準を、自ら作成することが含まれるという理解でよい。","answer":true,"explanation":"第3ステップでは、清掃・給油・点検を短時間で確実に行う自主保全仮基準を自ら作成します。"},
  {"id":456,"category":"設備の日常保全","text":"給油方法を見直す際は、油種を明確にして、できれば油種を統一するとされる。","answer":true,"explanation":"給油では油種・量・周期・箇所を明確にし、誤給油を防ぐため可能な範囲で油種を統一します。"},
  {"id":457,"category":"設備の日常保全","text":"自主保全第4ステップ（総点検）の目的の1つに、設備の構造・機能・原理とあるべき姿を理解することが挙げられるという理解でよい。","answer":true,"explanation":"総点検では、設備の構造・機能・原理を学び、五感点検と目で見る管理を身につけます。"},
  {"id":458,"category":"設備の日常保全","text":"自主保全第4ステップ（総点検）では、五感による点検は行わないようにすると考えられる。","answer":false,"explanation":"総点検では、設備の構造・機能・原理を学び、五感点検と目で見る管理を身につけます。"},
  {"id":459,"category":"設備の日常保全","text":"自主保全第5ステップ（自主点検）において、自主保全基準書を見直す際は、仮基準の作成時に設定した清掃の周期や時間を、変更してはならないという理解でよい。","answer":false,"explanation":"自主点検では仮基準を見直し、重複や抜けをなくして自主保全基準にまとめます。"},
  {"id":460,"category":"設備の日常保全","text":"自主保全第6ステップ（標準化）は、第1ステップから第5ステップの活動をしながら、 設備を取り巻く職場環境をよくする活動とされる。","answer":true,"explanation":"標準化では、設備だけでなく品質・安全・物流など職場全体の管理を標準化します。"},
  {"id":461,"category":"設備の日常保全","text":"自主保全第7ステップ（自主管理の徹底）では、自主保全活動の維持・向上などの活動を、 サークルが自主的に進めていくという理解でよい。","answer":true,"explanation":"第7ステップでは、目標管理と継続改善により自主管理を徹底します。"},
  {"id":462,"category":"改善・解析","text":"折れ線グラフは、数量の変化の状態を時系列で確認するのに適したグラフに該当する。","answer":true,"explanation":"折れ線グラフは、時間の経過に伴う数量の変化や傾向を見るのに適しています。"},
  {"id":463,"category":"改善・解析","text":"正規分布の形は、中心線の左右で面積の等しい長方形という位置づけである。","answer":false,"explanation":"正規分布は中央が高い左右対称のベル形の分布です。"},
  {"id":464,"category":"改善・解析","text":"標準偏差は、データのバラツキを数量的に表すものとされる。","answer":true,"explanation":"標準偏差は、データのばらつきの大きさを数値で表す指標です。"},
  {"id":465,"category":"改善・解析","text":"定められた作業時間内で、製品を生産できる能力を「工程能力」という。","answer":false,"explanation":"工程能力は、安定した工程が規格内の製品をつくる能力です。"},
  {"id":466,"category":"改善・解析","text":"突発的に発生するロスは、慢性的に発生するロスよりも、原因がつかみやすいことが多いという理解でよい。","answer":true,"explanation":"慢性ロスは原因が複雑に絡み合い、突発ロスより真因をつかみにくい傾向があります。"},
  {"id":467,"category":"改善・解析","text":"基礎事項として、PM分析では、現象を物理的に解析し、メカニズムを理解して生産活動の4要素（4M） との関連性を追求していくという理解でよい。","answer":true,"explanation":"PM分析は、現象を物理的に解析し、4Mとの関連から慢性ロスの要因を追究します。"},
  {"id":468,"category":"改善・解析","text":"IE（インダストリアル・エンジニアリング）は、図表を用いて、トラブル原因の対策を検討する手法とされる。","answer":false,"explanation":"IEは、人・設備・材料の動きや時間を分析し、生産性を高めるための工学的手法です。"},
  {"id":469,"category":"改善・解析","text":"5W2Hによる質問法において、2つの Hは、How（どのように）と How much（いくら） を示しているという理解でよい。","answer":true,"explanation":"5W2HはWho、What、When、Where、Why、How、How muchです。"},
  {"id":470,"category":"改善・解析","text":"動作研究は、設備の故障履歴から、最適なメンテナンス周期を決定するための研究を指す。","answer":false,"explanation":"動作研究は、作業者の動作を分析してムダを省き、より良い作業方法を設計します。"},
  {"id":471,"category":"改善・解析","text":"時間研究の目的の1つに、標準作業や標準時間の「あるべき姿」を設定することが含まれるという理解でよい。","answer":true,"explanation":"時間研究は作業時間を測定・分析し、標準時間の設定などに活用します。"},
  {"id":472,"category":"改善・解析","text":"ラインバランス分析は、製品の出荷量に対する在庫量のバランスが適切かどうか分析する手法とされる。","answer":false,"explanation":"ラインバランス分析は、各工程の作業時間の偏りを調べ、編成効率を高める手法です。"},
  {"id":473,"category":"改善・解析","text":"機械設備を止めて行う段取りのことを「内段取り」という。","answer":true,"explanation":"内段取りは設備を停止しなければできない段取り作業です。停止せず行えるものは外段取りです。"},
  {"id":474,"category":"改善・解析","text":"価値工学（VE）では、「価値」を「機能」と「コスト」で表すという理解でよい。","answer":true,"explanation":"VEでは価値を「機能÷コスト」で捉え、必要機能をより低い総コストで実現します。"},
  {"id":475,"category":"改善・解析","text":"FMEAは、設計品目の潜在故障がシステムに及ぼす影響度を解析するための手法という位置づけである。","answer":true,"explanation":"FMEAは、想定される故障モードと影響を事前に評価し、未然防止につなげる手法です。"},
  {"id":476,"category":"設備保全の基礎","text":"基礎事項として、「おねじ」は、円筒内にみぞを切ったねじのことを意味する。","answer":false,"explanation":"おねじは円筒の外側にねじ山を設けたものです。内側に設けるのはめねじです。"},
  {"id":477,"category":"設備保全の基礎","text":"キーは、機械や装置に、外部からの異物が侵入することを防ぐために利用されるという理解でよい。","answer":false,"explanation":"キーは軸と歯車・プーリーなどの回転体を固定し、トルクを伝える部品です。"},
  {"id":478,"category":"設備保全の基礎","text":"固定軸継手を利用する場合、軸の連結部分の調整（芯出し作業）は不要に該当する。","answer":false,"explanation":"固定軸継手は芯ずれを吸収しにくいため、正確な芯出しが必要です。"},
  {"id":479,"category":"設備保全の基礎","text":"基礎事項として、軸受には、ころがり軸受とすべり軸受があるという理解でよい。","answer":true,"explanation":"すべり軸受は油膜で軸を支持し、高速・高荷重や大型機器にも使用されます。"},
  {"id":480,"category":"設備保全の基礎","text":"密封装置（密封部品）に使われるゴムなどの封止部品を、ブッシュと呼ぶ。","answer":false,"explanation":"密封装置にはガスケット、パッキン、オイルシール、メカニカルシールなどがあります。"},
  {"id":481,"category":"設備保全の基礎","text":"歯車は、歯のかみ合いによって2軸間に動力を伝える装置と考えてよい。","answer":true,"explanation":"歯車は歯のかみ合いで回転と動力を正確に伝達します。軸間距離が長い場合はチェーンやベルトが適します。"},
  {"id":482,"category":"設備保全の基礎","text":"チェーン伝動装置は、すべりがなく、速度比が正確に該当する。","answer":true,"explanation":"チェーン伝動は原則として滑りがなく、一定の速度比で動力を伝えます。"},
  {"id":483,"category":"設備保全の基礎","text":"グリースのちょう度は、硬さを表す特性値という位置づけである。","answer":true,"explanation":"グリースのちょう度は、グリースの硬さ・軟らかさを表す指標です。"},
  {"id":484,"category":"設備保全の基礎","text":"空気圧装置は、一般的に、油圧装置よりも小型で大きな出力を得ることができるという理解でよい。","answer":false,"explanation":"一般に油圧は小型で大きな力を得やすく、空気圧は高速・清潔で扱いやすい特徴があります。"},
  {"id":485,"category":"設備保全の基礎","text":"空気圧装置において、空気の清浄化を目的とする機器には、エアタンクやアフタークーラーなどがあるという理解でよい。","answer":false,"explanation":"圧縮空気の清浄化には、フィルタ、ドレンセパレータ、エアドライヤなどを用います。"},
  {"id":486,"category":"設備保全の基礎","text":"油圧ポンプには、1回転あたりの吐出し量が変えられない定容量形と、変えられる可変容量形のものがあるとされる。","answer":true,"explanation":"油圧ポンプには、1回転当たりの吐出量が一定の定容量形と、変更できる可変容量形があります。"},
  {"id":487,"category":"設備保全の基礎","text":"アキュムレーターの例として、油圧シリンダーや油圧モーターなどが含まれるという理解でよい。","answer":false,"explanation":"アキュムレーターは油圧エネルギーを蓄え、圧力保持や脈動吸収などに使います。"},
  {"id":488,"category":"設備保全の基礎","text":"作動油の粘度指数は、温度変化の影響を受けず一定とされる。","answer":true,"explanation":"粘度指数が高い油ほど、温度変化による粘度変化が小さい油です。"},
  {"id":489,"category":"設備保全の基礎","text":"直流回路の電流は、「抵抗÷電圧」で求める。","answer":false,"explanation":"オームの法則では、電流＝電圧÷抵抗です。"},
  {"id":490,"category":"設備保全の基礎","text":"検電器は、交流の電圧、直流の電圧・電流・抵抗を、1台の計器で簡単に測定できる機器に該当する。","answer":false,"explanation":"検電器は電路の充電の有無を確認する器具です。電圧・電流・抵抗を測るのは回路計です。"},
  {"id":491,"category":"設備保全の基礎","text":"旋盤は、工作物を回転させ、刃物を当てて切削加工を行う工作機械である。","answer":true,"explanation":"旋盤では工作物側を回転させ、バイトを当てて外径・端面などを加工します。"},
  {"id":492,"category":"設備保全の基礎","text":"ステンレス鋼は、純鉄よりも腐食に強い金属材料とされる。","answer":true,"explanation":"ステンレス鋼はクロムなどを含み、一般に純鉄より耐食性に優れます。"},
  {"id":493,"category":"設備保全の基礎","text":"プラスチックは、成形加工や着色が容易で、電気絶縁性に優れた非金属材料と考えてよい。","answer":true,"explanation":"プラスチックは成形・着色がしやすく、一般に電気絶縁性に優れます。"},
  {"id":494,"category":"設備保全の基礎","text":"外側マイクロメータは、角度を測定するための測定器である。","answer":false,"explanation":"外側マイクロメータは主に外径や厚さを測定する器具で、角度測定には用いません。"},
  {"id":495,"category":"設備保全の基礎","text":"外側マイクロメータの測定値は、スリーブ目盛だけを読めば求められる。","answer":false,"explanation":"マイクロメータは、スリーブ目盛とシンブル目盛を合計して読み取ります。"},
  {"id":496,"category":"設備保全の基礎","text":"運転中のモーターの表面温度を測定する場合は、接触式の抵抗温度計よりも非接触式の放射温度計が適しているという理解でよい。","answer":true,"explanation":"回転体や高温部の表面温度は、安全に離れて測れる非接触式放射温度計が適します。"},
  {"id":497,"category":"設備保全の基礎","text":"差圧式流量計は、電気回路に流れる電流の量を測定する機器と考えてよい。","answer":false,"explanation":"差圧式流量計は、絞りの前後に生じる圧力差から流量を求めます。"},
  {"id":498,"category":"設備保全の基礎","text":"センタポンチは、アクリル板や木材、金属薄板を切断するための工具である。","answer":false,"explanation":"センタポンチは穴あけ位置の印付けに使う工具で、材料の切断には使用しません。"},
  {"id":499,"category":"設備保全の基礎","text":"リーマは、工作物にケガキ線を入れた後に、ドリルの穴あけ位置やケガキ線をはっきり示すための工具という位置づけである。","answer":false,"explanation":"リーマは、ドリルであけた穴を正確な寸法と滑らかな面に仕上げる工具です。"},
  {"id":500,"category":"設備保全の基礎","text":"寸法公差は、図面上の寸法と、現物の測定値との差とされる。","answer":false,"explanation":"寸法公差は、最大許容寸法と最小許容寸法の差です。図面寸法と実測値の差ではありません。"},
  {"id":501,"category":"生産の基本","text":"不安全状態は、災害や事故を起こす原因となる人の行動に該当する。","answer":false,"explanation":"不安全状態は設備・物・作業環境などの危険な状態です。人の危険な行動は不安全行動といいます。"},
  {"id":502,"category":"生産の基本","text":"安全衛生点検のうち、法令に基づく定期点検は、特定の検査技術や資格などを有する者が実施することが義務づけられているという理解でよい。","answer":true,"explanation":"法定点検には、必要な資格や検査能力を持つ者が実施するものがあります。"},
  {"id":503,"category":"生産の基本","text":"「ヒューマンエラー」は、人間の特性として避けられない人的な失敗のことを意味する。","answer":true,"explanation":"ヒューマンエラーは、人間の特性により起こり得る意図しない失敗や誤りです。"},
  {"id":504,"category":"生産の基本","text":"本質安全化は、作業者が注意力を最大限に発揮することで、安全を保つ方法と考えてよい。","answer":false,"explanation":"本質安全化は、危険源を除去したりエネルギーを低減したりして、設備そのものを安全にする考え方です。"},
  {"id":505,"category":"生産の基本","text":"基礎事項として、ハインリッヒの法則によると、1件の休業災害を起こす裏には、100件の不休災害があるとされているという理解でよい。","answer":false,"explanation":"ハインリッヒの法則では、1件の重大災害の背後に29件の軽傷事故と300件の無傷事故があるとされます。"},
  {"id":506,"category":"生産の基本","text":"酸素濃度が20％の場合、酸素欠乏状態にあると判断できる。","answer":false,"explanation":"酸素欠乏は空気中の酸素濃度が18％未満の状態です。"},
  {"id":507,"category":"生産の基本","text":"「フールプルーフ」は、作業者がエラーをしても、自動的に安全を確保でき、災害・事故につながらないようにする考え方を意味する。","answer":true,"explanation":"フールプルーフは、誤操作しても事故や不良につながりにくくする仕組みです。"},
  {"id":508,"category":"生産の基本","text":"リスクアセスメントは、人が行っていた作業を機械化・自動化することで、作業の効率化を図る手法と考えてよい。","answer":false,"explanation":"リスクアセスメントは危険性・有害性を特定し、リスクを見積もって除去・低減する手法です。"},
  {"id":509,"category":"生産の基本","text":"管理のサイクル（PDCAサイクル）は、Preparation（準備）→Decision（決定）→Calculation（見積もり）→Analysis（分析）のサイクルを回すことを指す。","answer":false,"explanation":"PDCAはPlan、Do、Check、Actionを繰り返す管理サイクルです。"},
  {"id":510,"category":"生産の基本","text":"三現主義は、実現、表現、再現を重視する考え方という位置づけである。","answer":false,"explanation":"三現主義は、現場・現物・現実を重視して事実を確認する考え方です。"},
  {"id":511,"category":"生産の基本","text":"5W1Hにおいて、5つの Wには、見る (Watch）、書く（Write）などが含まれるという理解でよい。","answer":false,"explanation":"5W1HはWho、What、When、Where、Why、Howです。"},
  {"id":512,"category":"生産の基本","text":"同一の生産条件から生産された全製品を、1個ずつ検査することを「抜取り検査」という。","answer":false,"explanation":"抜取り検査はロットの一部を抽出して合否を判定します。全品を調べるのは全数検査です。"},
  {"id":513,"category":"生産の基本","text":"作業標準には、作業の方法を手順ごとに書くだけでなく、作業の急所やコツなどを具体的に記入すると考えられる。","answer":true,"explanation":"作業標準には、条件・道具・手順に加えて、品質や安全上の急所・注意点も明記します。"},
  {"id":514,"category":"生産の基本","text":"メンバーシップは、集団を構成するメンバーとして、目標達成のため自己の能力・スキルを最大限活用して各自の役割を果たし、集団に貢献することという位置づけである。","answer":true,"explanation":"メンバーシップは、各自が能力を発揮し役割を果たして集団目標に貢献することです。"},
  {"id":515,"category":"生産の基本","text":"OJTは、仕事を通じた教育訓練とされる。","answer":true,"explanation":"OJTは、実際の仕事を通じて知識・技能を身につける教育訓練です。"},
  {"id":516,"category":"生産の基本","text":"自分の意志で知識、技術、技能を身につけることを「自己啓発」という。","answer":true,"explanation":"自己啓発は、本人が自らの意思で知識や技能を学ぶ活動です。"},
  {"id":517,"category":"生産の基本","text":"伝達教育は、本や映像などを用いて、人以外から学ぶ教育方法を指す。","answer":false,"explanation":"伝達教育は、学んだ人がその内容を職場のほかのメンバーへ伝える教育方法です。"},
  {"id":518,"category":"生産の基本","text":"生産のときに使う資源を少なくする考え方に当たるものが「リサイクル」である。","answer":false,"explanation":"リサイクルは、廃棄物を原材料などとして再生利用することです。"},
  {"id":519,"category":"生産の基本","text":"エコマークは、消費者が、環境保全に役立つ商品を選ぶための目印とされる。","answer":true,"explanation":"エコマークは、環境保全に役立つ商品を消費者が選ぶための目印です。"},
  {"id":520,"category":"設備の日常保全","text":"自主保全活動において、故障を直す活動は、改善活動に含まれるという理解でよい。","answer":false,"explanation":"故障や劣化を元の正しい状態へ戻すのは復元活動であり、改善活動とは区別します。"},
  {"id":521,"category":"効率化とロス","text":"保全手段の分類において、定期保全と予知保全は予防保全に含まれる。","answer":true,"explanation":"予防保全には、時間を基準とする定期保全と、状態を基準とする予知保全があります。"},
  {"id":522,"category":"効率化とロス","text":"生産保全は、生産性を高めるためのもっとも経済的な保全活動のことという位置づけである。","answer":true,"explanation":"生産保全は、設備のライフサイクル全体で生産性を最も経済的に高める保全活動です。"},
  {"id":523,"category":"効率化とロス","text":"保全予防（MP）では、新しい設備を計画、設計する段階で、保全費や劣化損失が少ない設備づくりを目指すという理解でよい。","answer":true,"explanation":"保全予防は、新設備の計画・設計段階から故障しにくく保全しやすい設備づくりを行う考え方です。"},
  {"id":524,"category":"効率化とロス","text":"TPMの基本理念の1つは、3Rの促進と考えてよい。","answer":false,"explanation":"TPMの基本理念には、予防哲学、ゼロ指向、全員参加があります。"},
  {"id":525,"category":"効率化とロス","text":"生産システムのアウトプット（効果）である PQCDSMEのうち、Dは「納期」に該当する。","answer":true,"explanation":"PQCDSMEのDはDelivery、すなわち納期を表します。"},
  {"id":526,"category":"効率化とロス","text":"管理上発生する手待ちロスに当たるものが「操業度を阻害するロス」である。","answer":false,"explanation":"管理上の指示待ち・材料待ちなどは管理ロスに該当し、操業度を阻害するロスとは区別します。"},
  {"id":527,"category":"効率化とロス","text":"「人の効率化を阻害するロスの5大ロス」を判定するための指標を、設備総合効率と呼ぶ。","answer":false,"explanation":"人の効率は、標準工数に対して実際に要した工数の関係などで評価します。"},
  {"id":528,"category":"効率化とロス","text":"原単位の効率化を阻害するロスである3大ロスの1つは、不良・手直しロスと考えてよい。","answer":false,"explanation":"不良・手直しロスは設備の7大ロスに含まれ、原単位の3大ロスとは別の分類です。"},
  {"id":529,"category":"効率化とロス","text":"測定調整ロスは、品質不良の発生・流出防止のため、測定調整を頻繁に実施する作業ロスに該当する。","answer":true,"explanation":"測定調整ロスは、不良の発生・流出防止のために繰り返す測定や調整の作業損失です。"},
  {"id":530,"category":"効率化とロス","text":"投入した材料の重量と、完成した良品の重量との差に当たるものが「歩留まりロス」である。","answer":true,"explanation":"歩留まりロスは、投入材料と良品として得られた材料との差に相当する損失です。"},
  {"id":531,"category":"効率化とロス","text":"速度稼働率は、「実際サイクルタイム÷基準サイクルタイム×100」で求める。","answer":false,"explanation":"速度稼働率は「基準サイクルタイム÷実際サイクルタイム×100」で算出します。"},
  {"id":532,"category":"効率化とロス","text":"潜在欠陥は、人為的タイプと時間的タイプの2つに分けられるという理解でよい。","answer":false,"explanation":"潜在欠陥は、物理的潜在欠陥と心理的潜在欠陥に分けて考えます。"},
  {"id":533,"category":"効率化とロス","text":"強制劣化の例として、決められた箇所に、適正な量・周期で給油していても、物理的に劣化が進行することが挙げられるという理解でよい。","answer":false,"explanation":"強制劣化は、清掃・給油・増し締めなどの基本条件を守らないことで人為的に進む劣化です。"},
  {"id":534,"category":"効率化とロス","text":"故障ゼロへの5つの対策の1つに「設計上の弱点を改善する」があるという理解でよい。","answer":true,"explanation":"故障ゼロには、基本条件の整備、使用条件の遵守、劣化復元、弱点改善、運転・保全技能向上が重要です。"},
  {"id":535,"category":"効率化とロス","text":"故障モードは、故障の原因が故障として表面に現れるまでの過程とされる。","answer":false,"explanation":"故障モードは、折損・摩耗・変形・漏れなど、故障が現れた状態の分類です。"},
  {"id":536,"category":"効率化とロス","text":"基礎事項として、機能停止型故障は、システムや設備の部分的な機能低下によって、歩留まりや速度の低下を発生させる故障と考えてよい。","answer":false,"explanation":"機能停止型故障は設備の機能が完全に失われる故障です。性能低下や歩留まり低下は機能低下型故障です。"},
  {"id":537,"category":"効率化とロス","text":"設備管理の観点では、ライフサイクルコスト（LCC）は、設備が故障してから再稼働するまでにかかる総費用のことを指す。","answer":false,"explanation":"LCCは、取得・運用・保全・廃棄まで、設備の生涯にかかる総費用です。"},
  {"id":538,"category":"効率化とロス","text":"基礎事項として、MTBFは、故障の修復にかかった時間の平均値という位置づけである。","answer":false,"explanation":"MTBFは、修理可能な設備における故障から次の故障までの平均稼働時間です。"},
  {"id":539,"category":"効率化とロス","text":"設備の保全を実施する際、要求された期間内に作業が終了する確率が低い設備は、保全性が低いと判断できる。","answer":true,"explanation":"保全性は、故障した設備を所定時間内に修復しやすい性質です。"},
  {"id":540,"category":"効率化とロス","text":"基礎事項として、MTTFは、修理可能な設備の故障から次の故障までの動作時間の平均値と考えてよい。","answer":false,"explanation":"MTTFは、修理しない機器が故障するまでの平均時間です。"},
  {"id":541,"category":"効率化とロス","text":"自主保全として実行する保全活動は、劣化を防ぐ活動、劣化を測る活動、劣化を復元する活動の3つに分類されるという理解でよい。","answer":true,"explanation":"自主保全の保全活動は、劣化を防ぐ・測る・復元する活動に整理できます。"},
  {"id":542,"category":"効率化とロス","text":"自主保全においてオペレーターに求められる4つの能力の1つに、時間管理能力があるという理解でよい。","answer":false,"explanation":"オペレーターには、異常発見、処置・回復、条件設定、維持管理などの能力が求められます。"},
  {"id":543,"category":"設備の日常保全","text":"日常の生産活動において、設備を正しく操作することは、自主保全に含まれるという理解でよい。","answer":true,"explanation":"正しい記述です。用語の定義と適用範囲をあわせて覚えておきましょう。"},
  {"id":544,"category":"設備の日常保全","text":"基礎事項として、自主保全のステップ方式では、1つのステップが完了した段階で管理者やスタッフによる診断を受け、合格すると次のステップに進むことができるという理解でよい。","answer":true,"explanation":"自主保全は各ステップを順に進め、診断に合格してから次のステップへ進みます。"},
  {"id":545,"category":"設備の日常保全","text":"自主保全では、オペレーターが行っていた保全業務を、全て保全部門に移行することを目的とすると考えられる。","answer":false,"explanation":"誤りです。記述中の対象・条件・定義のいずれかが正しくありません。"},
  {"id":546,"category":"設備の日常保全","text":"基礎事項として、重複小集団組織は、1つのグループにつき10人以上のメンバーで構成しなければならないという理解でよい。","answer":false,"explanation":"重複小集団は、階層ごとの小集団を重ねて方針と活動をつなぐ組織で、人数を10人以上に固定するものではありません。"},
  {"id":547,"category":"設備の日常保全","text":"配管・継手類からのにじみ・漏れのチェックは、設備が止まるまで実施できない自主保全活動とされる。","answer":false,"explanation":"誤りです。記述中の対象・条件・定義のいずれかが正しくありません。"},
  {"id":548,"category":"設備の日常保全","text":"活動板、ワンポイントレッスン、ミーティングのことを「自主保全活動の3種の神器」という。","answer":true,"explanation":"自主保全活動の3種の神器は、活動板・ワンポイントレッスン・ミーティングです。"},
  {"id":549,"category":"設備の日常保全","text":"エフ付けした後、その場で処置できる不具合については、その場で処置してエフ取りをすると考えられる。","answer":true,"explanation":"エフは、不具合・安全・保全性などの問題箇所を見える化し、処置状況を管理する札です。"},
  {"id":550,"category":"設備の日常保全","text":"定点撮影は、対象物を複数の角度から撮影することで、損傷箇所を発見する方式という位置づけである。","answer":false,"explanation":"定点撮影は同じ位置・角度から継続撮影し、改善前後の変化を比較する方法です。"},
  {"id":551,"category":"設備の日常保全","text":"基礎事項として、正しい状態から外れているものに対しては、改善活動を実施する前に、まず復元を実施するとされる。","answer":true,"explanation":"まず正しい状態へ復元し、その後に再発防止や機能向上の改善を行います。"},
  {"id":552,"category":"設備の日常保全","text":"マップによる管理では、不具合の状況を数値化して、定量的に変化を確認するという理解でよい。","answer":false,"explanation":"マップ管理は、不具合箇所や対策状況を設備・職場レイアウト上に表示する方法です。"},
  {"id":553,"category":"設備の日常保全","text":"基礎事項として、給油方法を見直す際は、油種を明確にして、できれば油種を統一すると考えられる。","answer":true,"explanation":"給油では油種・量・周期・箇所を明確にし、誤給油を防ぐため可能な範囲で油種を統一します。"},
  {"id":554,"category":"設備の日常保全","text":"自主保全第4ステップ ( 総点検 ) では、目で見る管理と並行して、五感点検をマスターする必要があるという理解でよい。","answer":true,"explanation":"総点検では、設備の構造・機能・原理を学び、五感点検と目で見る管理を身につけます。"},
  {"id":555,"category":"設備の日常保全","text":"自主保全第5ステップ（自主点検）では、これまでに作成した点検仮基準を見直し、点検ミスのない自主保全基準をまとめあげるという理解でよい。","answer":true,"explanation":"自主点検では仮基準を見直し、重複や抜けをなくして自主保全基準にまとめます。"},
  {"id":556,"category":"設備の日常保全","text":"自主保全第6ステップ（標準化）は、第1ステップから第5ステップの活動を行いながら、 設備を取り巻く職場環境をよくする活動と考えてよい。","answer":true,"explanation":"標準化では、設備だけでなく品質・安全・物流など職場全体の管理を標準化します。"},
  {"id":557,"category":"設備の日常保全","text":"自主保全活動における職場の目標は、工場の方針管理に基づき与えられるという理解でよい。","answer":true,"explanation":"正しい記述です。用語の定義と適用範囲をあわせて覚えておきましょう。"},
  {"id":558,"category":"改善・解析","text":"折れ線グラフは、構成割合を比較するのに適したグラフという位置づけである。","answer":false,"explanation":"折れ線グラフは、時間の経過に伴う数量の変化や傾向を見るのに適しています。"},
  {"id":559,"category":"改善・解析","text":"度数分布表は、ヒストグラムを作成するときのデータとなるという理解でよい。","answer":true,"explanation":"度数分布表はデータを階級ごとに集計し、ヒストグラム作成やばらつき把握に使います。"},
  {"id":560,"category":"改善・解析","text":"管理図の例として、p 管理図や np 管理図が挙げられるという理解でよい。","answer":true,"explanation":"管理図は、中心線と管理限界線を用いて工程が統計的に安定しているかを監視します。"},
  {"id":561,"category":"改善・解析","text":"正規分布の形は、中心線の左右で面積の等しい長方形に該当する。","answer":false,"explanation":"正規分布は中央が高い左右対称のベル形の分布です。"},
  {"id":562,"category":"改善・解析","text":"標準偏差は、データのバラツキを数量的に表すものという位置づけである。","answer":true,"explanation":"標準偏差は、データのばらつきの大きさを数値で表す指標です。"},
  {"id":563,"category":"改善・解析","text":"「工程能力」は、定められた作業時間内で、製品を生産できる能力を意味する。","answer":false,"explanation":"工程能力は、安定した工程が規格内の製品をつくる能力です。"},
  {"id":564,"category":"改善・解析","text":"なぜなぜ分析は、複数の危険源をスタートとして、それらが引き起こすすべての不具合を明確にする手法と考えてよい。","answer":false,"explanation":"なぜなぜ分析は、現象に対して「なぜ」を繰り返し、根本原因を追究する手法です。"},
  {"id":565,"category":"改善・解析","text":"PM分析の PMは、生産保全のことを指す。","answer":false,"explanation":"PM分析のPMはProductive Maintenanceではなく、現象を物理的に捉え、メカニズムと4Mの関係を追究する考え方を表します。"},
  {"id":566,"category":"改善・解析","text":"慢性的なロスは、突発的なロスよりも原因と結果の関係が複雑にからみ合っていることが多いという理解でよい。","answer":true,"explanation":"慢性ロスは原因が複雑に絡み合い、突発ロスより真因をつかみにくい傾向があります。"},
  {"id":567,"category":"改善・解析","text":"IE手法の例として、全数検査が含まれるという理解でよい。","answer":false,"explanation":"IEは、人・設備・材料の動きや時間を分析し、生産性を高めるための工学的手法です。"},
  {"id":568,"category":"改善・解析","text":"設備の故障履歴から、最適なメンテナンス周期を決定するための研究を「動作研究」という。","answer":false,"explanation":"動作研究は、作業者の動作を分析してムダを省き、より良い作業方法を設計します。"},
  {"id":569,"category":"改善・解析","text":"編成効率は、各工程の作業時間のバランスの良否を数値で判断するために活用されるという理解でよい。","answer":true,"explanation":"編成効率は、ライン全体の作業時間配分がどの程度均衡しているかを示します。"},
  {"id":570,"category":"改善・解析","text":"ラインバランス分析は、製品の出荷量に対する在庫量のバランスが適切かどうか分析する手法という位置づけである。","answer":false,"explanation":"ラインバランス分析は、各工程の作業時間の偏りを調べ、編成効率を高める手法です。"},
  {"id":571,"category":"改善・解析","text":"「内段取り」は、機械設備を止めて行う段取りのことを意味する。","answer":true,"explanation":"内段取りは設備を停止しなければできない段取り作業です。停止せず行えるものは外段取りです。"},
  {"id":572,"category":"改善・解析","text":"基礎事項として、価値工学（VE）では、「価値」を「機能」と「コスト」で表すという理解でよい。","answer":true,"explanation":"VEでは価値を「機能÷コスト」で捉え、必要機能をより低い総コストで実現します。"},
  {"id":573,"category":"改善・解析","text":"FTAは、樹形図を作成して、故障の発生原因などを予測・解析するための手法に該当する。","answer":true,"explanation":"FTAは、頂上事象から原因を樹形図で論理的に展開する解析手法です。"},
  {"id":574,"category":"設備保全の基礎","text":"ボルトのゆるみは、衝撃荷重や振動だけでなく、周囲の温度変化によっても起こるという理解でよい。","answer":true,"explanation":"正しい記述です。用語の定義と適用範囲をあわせて覚えておきましょう。"},
  {"id":575,"category":"設備保全の基礎","text":"キーは、軸と回転体を固定させるために使用されるという理解でよい。","answer":true,"explanation":"キーは軸と歯車・プーリーなどの回転体を固定し、トルクを伝える部品です。"},
  {"id":576,"category":"設備保全の基礎","text":"ピンは、機械や装置の内部からの液体漏れを防ぐために利用されるという理解でよい。","answer":false,"explanation":"ピンは部品の位置決め・連結・回り止めなどに使用します。密封部品ではありません。"},
  {"id":577,"category":"設備保全の基礎","text":"歯車は、2軸間の距離が比較的長いときに活用されるという理解でよい。","answer":false,"explanation":"歯車は歯のかみ合いで回転と動力を正確に伝達します。軸間距離が長い場合はチェーンやベルトが適します。"},
  {"id":578,"category":"設備保全の基礎","text":"密封装置（密封部品）には、ガスケットやメカニカルシールがあるという理解でよい。","answer":true,"explanation":"密封装置にはガスケット、パッキン、オイルシール、メカニカルシールなどがあります。"},
  {"id":579,"category":"設備保全の基礎","text":"すべり軸受は、高速回転に強く、タービンなどの大型機器の軸受として使用されるという理解でよい。","answer":true,"explanation":"すべり軸受は油膜で軸を支持し、高速・高荷重や大型機器にも使用されます。"},
  {"id":580,"category":"設備保全の基礎","text":"流体潤滑は、物質と物質の間に形成された油膜が、きわめて薄い状態で部分的にこすっている現象と考えてよい。","answer":false,"explanation":"流体潤滑では、十分な厚さの油膜が形成され、固体面同士がほぼ接触しません。"},
  {"id":581,"category":"設備保全の基礎","text":"潤滑油は、グリースより冷却効果が大きいという理解でよい。","answer":true,"explanation":"潤滑油は循環させやすく、一般にグリースより冷却効果に優れます。"},
  {"id":582,"category":"設備保全の基礎","text":"基礎事項として、空気圧装置において、空気の清浄化を目的とする機器には、エアタンクやアフタークーラーなどがあるという理解でよい。","answer":false,"explanation":"圧縮空気の清浄化には、フィルタ、ドレンセパレータ、エアドライヤなどを用います。"},
  {"id":583,"category":"設備保全の基礎","text":"密閉容器中の油の一部に加えられた圧力は、すべての方向に等しい大きさで作用するとされる。","answer":true,"explanation":"正しい記述です。用語の定義と適用範囲をあわせて覚えておきましょう。"},
  {"id":584,"category":"設備保全の基礎","text":"直流回路の電流は、「抵抗÷電圧」で算出できる。","answer":false,"explanation":"オームの法則では、電流＝電圧÷抵抗です。"},
  {"id":585,"category":"設備保全の基礎","text":"接地は、電気機器や配線類などの絶縁不良や損傷により、電流が他に漏れて流れている現象に該当する。","answer":false,"explanation":"接地は電気機器の金属部などを大地へ接続する安全措置です。絶縁不良で電流が漏れる現象は漏電です。"},
  {"id":586,"category":"設備保全の基礎","text":"回路計 ( テスター ) での抵抗測定は、測定対象設備の運転中に実施するものとされる。","answer":false,"explanation":"抵抗測定は必ず回路の電源を切り、無電圧を確認して行います。"},
  {"id":587,"category":"設備保全の基礎","text":"基礎事項として、インバーターは、低圧回路の電路保護に使用される遮断器とされる。","answer":false,"explanation":"インバーターは周波数や電圧を制御し、主にモーターの回転速度を調整します。"},
  {"id":588,"category":"設備保全の基礎","text":"安全弁は、規定圧力以上になった場合に圧力を逃がすための機器と考えてよい。","answer":true,"explanation":"安全弁は圧力が設定値を超えたときに流体を逃がし、機器を保護します。"},
  {"id":589,"category":"設備保全の基礎","text":"空気圧装置に使用されるアクチュエーターは、圧縮空気エネルギーを機械エネルギーに変える機器に該当する。","answer":true,"explanation":"アクチュエーターは流体や電気のエネルギーを機械的な運動へ変換します。"},
  {"id":590,"category":"設備保全の基礎","text":"基礎事項として、油圧バルブのうち、圧力制御弁は、アクチュエーターの仕事の大きさを決める弁という位置づけである。","answer":true,"explanation":"圧力制御弁は圧力を調整し、アクチュエーターが発生する力・トルクを制御します。"},
  {"id":591,"category":"設備保全の基礎","text":"油圧シリンダーは、流体エネルギーを直線往復運動に変換できる機器とされる。","answer":true,"explanation":"油圧シリンダーは油圧エネルギーを直線往復運動へ変換します。"},
  {"id":592,"category":"設備保全の基礎","text":"光電センサーは、主に温度の変化を検出するセンサーと考えてよい。","answer":false,"explanation":"光電センサーは投光・受光による光量変化で物体の有無や位置を検出します。"},
  {"id":593,"category":"設備保全の基礎","text":"フライス盤は、ドリルで穴あけを実行する工作機械に該当する。","answer":false,"explanation":"フライス盤は回転するフライス工具で平面・溝などを加工します。"},
  {"id":594,"category":"設備保全の基礎","text":"合金鋼は、2種類以上の異なる金属板を重ね合わせたものという位置づけである。","answer":false,"explanation":"合金鋼は鉄にニッケル、クロムなどの合金元素を加えて性質を改善した鋼です。"},
  {"id":595,"category":"設備保全の基礎","text":"一般的な M型ノギスでは、0.05mm（1/20mm）単位で長さの測定が可能とされる。","answer":true,"explanation":"一般的なM形ノギスは、外側・内側・深さを0.05mm単位で測定できます。"},
  {"id":596,"category":"設備保全の基礎","text":"水準器や傾斜計は、設備や部材の傾き・角度を確認するために使用される。","answer":true,"explanation":"水準器や傾斜計は、水平・垂直や傾斜角の確認に用います。"},
  {"id":597,"category":"設備保全の基礎","text":"リーマは、工作物にケガキ線を入れた後に、ドリルの穴あけ位置やケガキ線をはっきり示すための工具に該当する。","answer":false,"explanation":"リーマは、ドリルであけた穴を正確な寸法と滑らかな面に仕上げる工具です。"},
  {"id":598,"category":"設備保全の基礎","text":"ハンドタップは、めねじを切る切削工具という位置づけである。","answer":true,"explanation":"ハンドタップは、下穴にめねじを加工する切削工具です。"},
  {"id":599,"category":"設備保全の基礎","text":"基礎事項として、寸法公差は、図面上の寸法と、現物の測定値との差とされる。","answer":false,"explanation":"寸法公差は、最大許容寸法と最小許容寸法の差です。図面寸法と実測値の差ではありません。"},
  {"id":600,"category":"設備保全の基礎","text":"穴と軸が互いにはまりあう関係のことを「はめあい」という。","answer":true,"explanation":"はめあいは、穴と軸の寸法関係によるすきま・締めしろの状態を表します。"}
];
